const conditionMap=new Map(conditionRecords.map(r=>[r.uid,r]));
const specialConditionIds=new Set(['0x87000003','0x87000006','0x8700000A','0x87000016','0x87000052','0x87000065','0x87000073','0x8700008F']);
function conditionUid(uid){if(typeof uid!=='string'||! /^(?:0x)?[0-9a-f]{8}$/i.test(uid))throw new Error('状態UIDは8桁の16進文字列です');return '0x'+uid.replace(/^0x/i,'').toUpperCase();}
function conditionRecord(uid){const r=conditionMap.get(conditionMap.has(uid)?uid:conditionUid(uid));if(!r)throw new Error('未収録の状態UIDです');return r;}
function conditionRankValue(uid,rank){const r=conditionRecord(uid);integer(rank,'rank',-0x80000000,0x7fffffff);if(!Array.isArray(r.rank_values)||r.rank_values.length!==20)throw new Error('この状態には換算表がありません');return r.rank_values[Math.max(-9,Math.min(10,rank))+9];}
function conditionResistance(uid,rank){const r=conditionRecord(uid);integer(rank,'resistance rank',-0x80000000,0x7fffffff);return r.resistance==='0x00000000'?100:conditionRankValue(r.resistance,rank);}
function conditionAntennaAtLevel(groupUid,level){integer(level,'level',1,999999);const id=conditionUid(groupUid),rows=conditionAntennaRanks.filter(r=>r.group_uid===id);if(!rows.length)throw new Error('未収録の状態付与アンテナ系統です');return rows.filter(r=>r.level<=level).sort((a,b)=>b.level-a.level||b.rank-a.rank)[0]??null;}
function rollConditionAntenna(row,options={}){if(!conditionAntennaRanks.includes(row))throw new Error('状態付与アンテナの監査レコードを指定してください');return rollCondition({...options,uid:row.condition_uid,value:row.condition_value,A:row.A,turnMin:row.turn_min,turnMax:row.turn_max});}
function conditionChance({uid,A,resistanceRank=0}){conditionRecord(uid);integer(A,'A',0,31);const resistance=conditionResistance(uid,resistanceRank),numerator=A===31?3000:Math.min(3000,A*resistance);return {numerator,denominator:3000,nominalProbability:numerator/3000,resistance,bypass:A===31};}

// LotConditionAdd ordinary probability/duration core AFTER CanAddCondition.
// Eligibility is deliberately required; probability=100% must not bypass immunity.
function rollCondition({uid,value,A,turnMin=0,turnMax=0,resistanceRank=0,eligible,mode='execute',seed,randRange,route='normal-enemy'}={}){
  const record=conditionRecord(uid);uid=record.uid;
  if(uid==='0x87000065')throw new Error('全能力変化はLotConditionAddUpDownStatusAllの専用抽選が必要です');
  integer(value,'value',-0x80000000,0x7fffffff);integer(turnMin,'turnMin',0,15);integer(turnMax,'turnMax',0,15);
  if(!['normal-enemy','normal-ally'].includes(route))throw new Error('通常の敵・味方対象経路を指定してください');
  if(typeof eligible!=='boolean')throw new TypeError('CanAddCondition等を確認したeligibleの指定が必要です');
  if(!['execute','predict'].includes(mode))throw new Error('modeが不正です');
  if(seed!==undefined){integer(seed,'seed',0,0xffffffff);if(randRange!==undefined)throw new Error('seedとrandRangeは片方だけ指定してください');if(mode==='predict'&&seed!==0)throw new Error('予測に実行seedを指定しないでください');}
  const chance=conditionChance({uid,A,resistanceRank}),trace=[];
  // 949A3C: ordinary same-side effects use resistance 100. Eligibility is separate.
  if(route==='normal-ally')Object.assign(chance,{resistance:100,numerator:A===31?3000:A*100,nominalProbability:A===31?1:A/30});
  if(!eligible)return {success:false,reason:'ineligible',mode,uid,chance,trace};
  if(mode==='predict')return {success:true,reason:'prediction-no-lottery',mode,uid,value,turns:turnMin,chance,trace};
  // LotConditionAdd 0x949B28 skips both lotteries for a zero input seed.
  if(seed===0)return {success:true,reason:'zero-seed-no-lottery',mode,uid,value,turns:turnMin,chance,trace};
  const rng=seed===undefined?randRange:createGsRandom((seed+Number(uid))>>>0).randRange;
  const sample=(size,label)=>{const result=draw(rng,size,label);trace.push({label,size,result});return result;};
  if(!chance.bypass&&chance.numerator<3000&&sample(3000,'condition-success')>=chance.numerator)return {success:false,reason:'lottery-failed',mode,uid,chance,trace};
  const turns=turnMin!==0&&turnMax>turnMin?turnMin+sample(turnMax-turnMin+1,'condition-duration'):turnMin;
  return {success:true,reason:'lottery-passed',mode,uid,value,turns,chance,trace};
}

function conditionState(uid,{base=0,current=base,remainingTurns=0,statRevision}={}){
  const r=conditionRecord(uid);integer(base,'base',r.minimum,r.maximum);integer(current,'current',r.minimum,r.maximum);integer(remainingTurns,'remainingTurns',0,0xffffffff);
  if(statRevision!==undefined)integer(statRevision,'statRevision',0);
  return {uid:r.uid,base,current,remainingTurns,...(statRevision===undefined?{}:{statRevision})};
}
function mergeCondition(state,value,turns,{statusVersion}={}){
  const s=conditionState(state.uid,state),r=conditionRecord(s.uid);integer(value,'incoming value',r.minimum,r.maximum);integer(turns,'incoming turns',0,15);integer(statusVersion,'StatusVersion',1,9999);
  if(specialConditionIds.has(s.uid))throw new Error('複合・専用状態は通常の重ね掛けへ直接渡せません');
  return mergeConditionValue(s,value,turns,statusVersion);
}
function mergeConditionValue(s,value,turns,statusVersion){
  const r=conditionRecord(s.uid);integer(value,'incoming value',-0x80000000,0x7fffffff);integer(turns,'incoming turns',0,15);
  const mode=r.value_merge,flags=Number(r.words[14]);let current=s.current;
  if(mode===0)current=value;
  else if(mode===1||mode===2){if(mode===2&&statusVersion>=5&&s.current===r.maximum)return s;current=Math.max(r.minimum,Math.min(r.maximum-(mode===2?1:0),s.current+value));}
  else if(mode===3)current=Math.max(s.current,value);
  else if(mode===4)current=s.current===0?value:Math.min(s.current,value);
  else throw new Error('未対応の状態値更新方式です');
  if(current===s.current&&(flags&0x1c000000)===0)return s;
  let remainingTurns=s.remainingTurns;
  const keepPermanent=(statusVersion>=7?s.current!==s.base:s.current!==0)&&s.remainingTurns===0;
  if(!keepPermanent){
    if(r.timer_merge===1)remainingTurns=Math.min(10,s.remainingTurns+turns);
    else if(r.timer_merge===3)remainingTurns=Math.max(s.remainingTurns,turns);
    else if(r.timer_merge===4)remainingTurns=s.remainingTurns===0?turns:Math.min(s.remainingTurns,turns);
  }
  return {...s,current,remainingTurns:current===s.base?0:remainingTurns,...(s.statRevision===undefined?{}:{statRevision:s.statRevision+1})};
}
function tickCondition(state){const s=conditionState(state.uid,state);if(s.remainingTurns===0)return s;const remainingTurns=s.remainingTurns-1;return {...s,remainingTurns,current:remainingTurns===0?s.base:s.current,...(s.statRevision!==undefined&&remainingTurns===0?{statRevision:s.statRevision+1}:{})};}
function resetCondition(state){const s=conditionState(state.uid,state);return {...s,current:s.base,remainingTurns:0,...(s.statRevision===undefined?{}:{statRevision:s.statRevision+1})};}
function cureConditions(states,{group='all',target='ally',uid}={}){
  if(!['all','attribute','single'].includes(group)||!['ally','enemy'].includes(target))throw new Error('治療のgroup/targetが不正です');
  const single=group==='single'?conditionRecord(uid).uid:null;
  if(!Array.isArray(states))throw new TypeError('statesは配列です');
  return states.map(state=>{const s=conditionState(state.uid,state),r=conditionRecord(s.uid),selected=group==='single'?s.uid===single:group==='all'?r.all_cure:r.attribute_cure;
    const harmful=(Number(r.words[14])&0x1000)!==0;
    return selected&&(target==='enemy'||s.current<=s.base||harmful)?resetCondition(s):s;
  });
}

const slipIds=new Set(['0x8700001A','0x87000048','0x870000A6','0x87000007','0x87000074','0x87000066','0x8700009D','0x87000093']);
function conditionSlipDamage(uid,value,maxHp){const r=conditionRecord(uid);integer(value,'slip value',r.minimum,r.maximum);integer(maxHp,'maxHp',1,9999999);if(!slipIds.has(r.uid))throw new Error('スリップ対象外の状態です');if(value<=0)return 0;return Math.min(r.rank_cap,Math.max(1,mulDiv([maxHp,conditionRankValue(r.uid,value)],100)));}
function movementBlockers(states){return states.map(s=>conditionState(s.uid,s)).filter(s=>s.current>0&&['0x87000077','0x870000B3','0x87000049','0x870000B8','0x8700009F'].includes(s.uid)).map(s=>s.uid);}

function applyConditionResult(state,result,options){
  if(!result||!['execute','predict'].includes(result.mode)||typeof result.success!=='boolean')throw new Error('状態抽選結果が必要です');
  const original=conditionState(state.uid,state);
  if(result.mode==='predict')throw new Error('AI予測結果を実状態へ適用しないでください');
  if(result.uid!==original.uid)throw new Error('結果と状態のUIDが一致しません');
  if(!result.success)return original;
  if(result.uid==='0x87000081'&&result.turns===0)throw new Error('突然死は死亡結果の適用が必要です。通常状態として保存しないでください');
  return mergeCondition(original,result.value,result.turns,options);
}
function conditionEffectView(states){
  const values=new Map(states.map(s=>{const v=conditionState(s.uid,s);return [v.uid,v.current];}));
  const get=uid=>values.get(uid)??0;
  return {movementBlockers:movementBlockers(states),antennaSealed:get('0x87000019')>0,breathSealed:get('0x870000B5')>0,
    statStages:{attack:get('0x87000028'),defense:get('0x87000013'),speed:get('0x87000010'),evasion:get('0x87000014')},
    evasionDelta:2*get('0x87000014'),jackValue:get('0x8700005F'),excited:get('0x87000075')>0,
    skipOrdinaryEvasion:['0x87000075','0x87000077','0x870000B3','0x870000B8','0x8700009F','0x87000049'].some(uid=>get(uid)>0),
    elementalStatusValues:[0,...['0x87000048','0x870000A6','0x87000007','0x87000074','0x87000066','0x8700009D'].map(get),0,get('0x87000093')]};
}
function rollExcitement({sureHit,randRange}){
  if(typeof sureHit!=='boolean')throw new TypeError('sureHitはbooleanです');
  const roll=draw(randRange,100,'excitement');
  return {roll,forcedCritical:roll<20,failed:roll>=20&&!sureHit,continueNormalCritical:roll>=20&&sureHit};
}
function additionalConditionA(family,stage){integer(stage,'equipment stage',1,9);
  const tables={slipOrStatDown:[24,20,16,13,10,8,6,4,2],disruption:[4,8,12,15,18,21,24,27,30]};
  if(!Object.hasOwn(tables,family))throw new Error('対応する追加異常・ボディの系列を指定してください');return tables[family][stage-1];
}
// Historical probability-only interface. The native enum order was checked
// against GetJackingType; command selection is handled separately.
function rollJackAction({stage,randRange,profile}){
  if(profile!=='provided-research')throw new Error('ジャック行動表はprovided-researchを明示して利用してください');
  integer(stage,'jack stage',0,9);if(stage===0)return {action:'normal',source:profile,roll:null};
  const weight=Math.min(stage,4)*10,roll=draw(randRange,20+weight,'jack-action');
  return {action:roll<10?'idle':roll<20?'normal':'reverse-target-side',source:profile,roll};
}

// Input eligibility must include damage success, survival, and CanAddCondition.
function rollShotCondition(row,options={}){
  if(!row||typeof row.condition_uid!=='string')throw new Error('属性アンテナの監査レコードが必要です');
  if(options.mode==='predict')return {success:false,reason:'prediction-skips-shot-condition',mode:'predict'};
  if(Number(row.condition_uid)===0)return {success:false,reason:'no-additional-condition',mode:'execute'};
  return rollCondition({...options,uid:row.condition_uid,value:row.condition_value,A:row.condition_A,turnMin:row.turn_min,turnMax:row.turn_max});
}

// AddConditionValue D1BCB8: dispatch is distinct from CanAddCondition. Once
// a compound result succeeds, each child is written without another lottery.
// This transaction returns new states; unresolved flags cannot partially apply.
function applyConditionValues(states,result,{statusVersion,canWrite}={}){
  integer(statusVersion,'StatusVersion',1,9999);
  if(!result||result.mode!=='execute'||typeof result.success!=='boolean')throw Error('An execution condition result is required');
  const uid=/^(?:0x)?00000000$/i.test(String(result.uid))?'0x00000000':conditionRecord(result.uid).uid;
  const next=states.map(s=>conditionState(s.uid,s)),changes=[];
  if(!result.success||uid==='0x00000000')return {states:next,changes};
  const value=result.value,turns=result.turns;
  integer(value,'incoming value',-0x80000000,0x7fffffff);integer(turns,'incoming turns',0,15);
  const noWrite=new Set(['0x87000006','0x8700000A','0x87000052']);
  const compound=new Set(['0x87000016','0x87000065','0x87000073','0x8700008F']);
  const read=id=>next.find(s=>s.uid===id)??conditionState(id);
  const allowed=id=>{
    const flag=canWrite?.(id);
    if(typeof flag!=='boolean')throw Error('GetConditionFlagData bit0 is required for '+id);
    return flag;
  };
  const save=(before,after)=>{
    const index=next.findIndex(s=>s.uid===after.uid);
    if(index<0)next.push(after);else next[index]=after;
    changes.push({uid:after.uid,before:{...before},after:{...after}});
  };
  const add=(id,incoming,duration)=>{
    if(noWrite.has(id))return;
    if(compound.has(id)){for(const child of expandClearCondition(id).uids)add(child,incoming,duration);return;}
    // UseResultCoreHitConditionAdd 9545C0: only duration zero invokes SetDead.
    // A nonzero duration delegates to the ordinary AddConditionValue path.
    if(id==='0x87000081'&&duration===0)throw Error('Instant death must be applied as a death result');
    if(id==='0x87000003'&&statusVersion>=2){
      // Native order: attack, defense, speed, evasion, 83, 2D. Positive current
      // values reset; negative deltas retain permanence or use incoming duration.
      for(const stat of ['0x87000028','0x87000013','0x87000010','0x87000014','0x87000083','0x8700002D']){
        const before=read(stat),delta=before.current-before.base;
        if(before.current<=0&&before.remainingTurns>=duration)continue;
        if(allowed(stat))save(before,resetCondition(before));
        if(delta<0)add(stat,delta,before.remainingTurns===0?0:duration);
      }
    }
    if(!allowed(id))return;
    const before=read(id),after=mergeConditionValue(before,incoming,duration,statusVersion);
    save(before,after);
  };
  add(uid,value,turns);
  return {states:next,changes};
}


// UseResultCoreHitConditionAdd 954604-954668. This is a hit-result payload,
// unlike AddConditionValue(65), which broadcasts a scalar to all four stats.
function applyConditionHitResult(states,result,options={}){
  if(Number(result?.uid)!==0x87000065&&String(result?.uid).toUpperCase()!=='87000065')return applyConditionValues(states,result,options);
  if(result.mode!=='execute'||typeof result.success!=='boolean')throw Error('An execution condition result is required');
  if(!result.success)return applyConditionValues(states,result,options);
  integer(result.value,'packed stat values',-0x80000000,0xffffffff);
  integer(result.turns,'packed stat turns',0,0xffffffff);
  let next=states.map(s=>conditionState(s.uid,s));const changes=[];
  for(const [index,uid] of ['0x87000028','0x87000013','0x87000010','0x87000014'].entries()){
    const value=(result.value<<(24-index*8))>>24,turns=(result.turns>>>(index*8))&255;
    if(value===0)continue;
    const applied=applyConditionValues(next,{...result,uid,value,turns},options);
    next=applied.states;changes.push(...applied.changes);
  }
  return {states:next,changes};
}


// LotConditionAddUpDownStatusAll 94A8A4: each component uses the SAME outer
// seed and its own UID. The first successful component supplies packed duration.
function rollAllStatConditions({conditionFor,seed,...options}={}){
  integer(seed,'condition seed',0,0xffffffff);
  if(typeof conditionFor!=='function')throw Error('Per-stat eligibility and resistance are required');
  if(options.randRange!==undefined)throw Error('Compound lottery requires independent UID-seeded streams');
  const children=[];
  for(const uid of ['0x87000028','0x87000013','0x87000010','0x87000014']){
    const context=conditionFor(uid);
    if(!context||typeof context.eligible!=='boolean')throw Error('Unresolved per-stat eligibility: '+uid);
    children.push(rollCondition({...options,eligible:context.eligible,resistanceRank:context.resistanceRank,uid,seed}));
  }
  const first=children.find(child=>child.success);
  let value=0,turns=0;
  if(first)for(const [index,child] of children.entries())if(child.success){
    value|=(Math.max(-128,Math.min(127,child.value))&255)<<(index*8);
    turns|=Math.min(255,first.turns)<<(index*8);
  }
  return {uid:'0x87000065',mode:options.mode??'execute',success:!!first,
    reason:first?'compound-lottery-passed':'compound-no-success',value:value|0,turns:turns>>>0,children,
    trace:children.flatMap(child=>child.trace.map(draw=>({...draw,uid:child.uid})))};
}

