    if(c.score!==best.score)continue;
    if(c.currentHpSum!==best.currentHpSum){if(high?c.currentHpSum>best.currentHpSum:c.currentHpSum<best.currentHpSum)best=c;continue;}
    if(c.maxHpSum>best.maxHpSum)best=c;
