  if(actor.hp<=0||actor.enabled===false||actor.escaped||actor.rental||movementBlockers(actor.conditions).length)return {selected:null,reason:'actor-cannot-move'};
  if(actor.conditions.some(c=>c.uid==='0x8700005F'&&c.current!==0))throw new Error('ジャック中の候補選択経路は未接続です');
  if(!complete)throw new Error('候補生成・予測が完了したcomplete:trueの指定が必要です');
  if(candidates.some(c=>c.selectionReady===false))throw new Error('使用条件・候補列が未解決の予測候補は自動採用できません');
