function healPredictionAmount(data,{hp,maxHp}) {
  integer(hp,'HP',0,0x7fffffff);integer(maxHp,'最大HP',1,0x7fffffff);
  integer(data.low,'SUBHEAL下限',0,0x7fffffff);integer(data.modifier,'Action補正',-100,127);
  integer(data.flags,'SUBHEAL flags',0,0xffffffff);
  const base=data.low,percentage=(data.flags&1)!==0;
  const scaled=percentage?Number(BigInt(maxHp)*BigInt(Math.min(100,base))/100n):base;
  const adjusted=Number(BigInt(scaled)*BigInt(100+data.modifier)/100n);
  const hpGain=Math.min(adjusted,Math.max(0,maxHp-hp));
  return {hpGain,base,percentage,scaled,adjusted,success:hpGain!==0};
}

// Build successful scoring results without applying healing to real or scratch HP.
// The remaining native CheckTurnAct/CanHitAction gate must be explicitly resolved.
function predictHealCandidatesWork(state,actor,options={}) {
  const {sideMap,battleMode,battleVersion,implCounter,resolveEligibility,targetInfo,levelDifference,registeredCount,deadCount}=options;
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const action=actor.antenna?.action;
  const pending=reason=>({complete:false,selectionReady:false,candidates:[],reason});
  if(!action||![0x32,0x37].includes(Number(action.type)))return pending('not-heal-or-revival');
  const data=healActionData.find(r=>r.actionUid===action.action_uid);
  if(!data||data.type!==Number(action.type)||data.subUid!==action.sub_uid)return pending('heal-data-mismatch');
  if(actor.enabled===false||actor.hp<=0||actor.escaped||actor.rental||movementBlockers(actor.conditions).length)return {complete:true,selectionReady:false,candidates:[],reason:'cannot-act'};
  if((battleConditionValue(actor,'8700005F')!==0&&![2,3].includes(options.jackType)))return pending('jack-route');
  if(battleMode!==0||battleVersion<1)return pending('special-battle-mode');
  const repeat=battleActionRepeats(actor,{kind:'antenna',battleVersion,implCounter,apCost:data.apCost});
  if(repeat.apEligible===0)return {complete:true,selectionReady:false,candidates:[],repeat,reason:repeat.sealed?'antenna-sealed':'insufficient-ap'};
  const generated=battleAntennaTargetCandidates(state,actor,{sideMap,battleMode,jackType:options.jackType??0});
  if(!generated.complete)return {...generated,selectionReady:false};
  const candidates=[];
  for(const candidate of generated.candidates){
    const results=[],rawResults=[];
    for(let hitIndex=0;hitIndex<repeat.apEligible;hitIndex++){
      const outer=battleCheckTurnAct(actor,action,{turnNumber:hitIndex+1,canMove:options.canMove});
      if(!outer.complete)return {...pending(outer.reason),candidates};
      if(!outer.allowed)continue;
      const targets=[];
      for(const target of candidate.targets){
        const defender=state.parties[target.side].members[target.slot];
        const nativeTarget=battleTargetEligibility(defender,action,{statusVersion:state.statusVersion});
        if(!nativeTarget.complete)return {...pending(nativeTarget.reason),candidates};
        if(!nativeTarget.allowed)continue;
        const gate=typeof resolveEligibility==='function'?resolveEligibility({actor,defender,action,hitIndex,candidate}):nativeTarget;
        if(gate?.complete!==true||typeof gate.allowed!=='boolean')return {...pending('native-eligibility-unresolved'),candidates,pending:{target,hitIndex}};
        if(gate.allowed)targets.push(defender);
      }
      if(!targets.length)continue;
      const generated=generateHealTurn(state,actor,data,targets,{turnParameter:hitIndex,mode:'predict'});
      rawResults.push(...generated.generatedResults);
      for(const row of generated.generatedResults)if(row.type===2){
        const defender=state.parties[row.target.side].members[row.target.slot];
        const numeric=healPredictionAmount(data,{hp:defender.hp,maxHp:defender.initialStats.hp});
        results.push({...row,kind:Number(action.type)===0x37?'revival':'heal',hitIndex,hpGain:row.amount,numeric});
      }
    }
    const evaluation=scoreHealRevivalPrediction(state,action,results,{targetInfo,levelDifference,registeredCount,deadCount});
    candidates.push({...candidate,...evaluation,targets:candidate.targets,scoredTargets:evaluation.targets,results,rawResults,selectionReady:false});
  }
  return {complete:true,scope:'heal-revival-successful-result-prediction',selectionReady:false,repeat,candidates};
}

// Direct prediction calls receive an isolated working battle, just like the
// common antenna entry. Provider failures must not publish partial state writes.
function battlePredictHealCandidates(state,actor,options={}){
 let location;
 state.parties.forEach((party,side)=>{const slot=party.members.indexOf(actor);if(slot!==-1)location={side,slot};});
 if(!location)throw Error("戦闘内の使用者が必要です");
 const work=structuredClone(state);
 return predictHealCandidatesWork(work,work.parties[location.side].members[location.slot],options);
}


// BattleRound::IsEndBattle 93CB00–93CC54. This is not a winner calculation.
function battleIsEnd(state,{battleMode,sideMap}={}) {
  integer(battleMode,'Impl+1C',0,0xffffffff);
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw new Error('UI側から内部側へのsideMapが必要です');
  const side=internal=>state.parties[sideMap.indexOf(internal)].members.filter(Boolean);
  const available=a=>a.enabled!==false&&a.hp>0&&!a.rental;
  if(battleMode!==3){
    let alive=false;
    for(const a of side(0)){if(!available(a))continue;if(a.escaped)return true;alive=true;}
    if(!alive)return true;
  }
  const count=side(1).filter(a=>available(a)&&!a.escaped).length;
  return count<(battleMode===3?2:1);
}


// SpecialDecision 92AC7C–92AEAC: select the order prefix BEFORE cloning Round.
// Rows carry native CanMove and party-command values, not display button labels.
function specialDecisionOrderPrefix(order,{battleVersion}={}) {
  integer(battleVersion,'BattleVersion',1,9999);
  if(!Array.isArray(order)||order.length===0||order.length>20)throw new Error('1～20件の現在行動順が必要です');
  const validate=row=>{integer(row.side,'内部陣営',0,1);integer(row.slot,'内部位置',0,9);};
  validate(order[0]);const prefix=[{...order[0]}],side=order[0].side;
  const done=(reason,extra={})=>({complete:true,scope:'special-decision-order-prefix',prefix,reason,...extra});
  for(let i=1;i<order.length;i++){
    const row=order[i];validate(row);
    if(typeof row.canMove!=='boolean')return {complete:false,reason:'native-can-move-unresolved',index:i,prefix};
    // Cannot-move entries are copied even when they belong to the opposing party.
    if(!row.canMove){prefix.push({...row});continue;}
    if(row.side!==side)return done('next-moving-opponent');
    if(typeof row.jacked!=='boolean')return {complete:false,reason:'jack-state-unresolved',index:i,prefix};
    if(row.jacked)return battleVersion>=6?done('jacked-aborts-special-decision',{aborted:true}):done('jacked-ends-prefix');
    integer(row.commandType,'BattlePartyCommand+14',0,0xffffffff);
    if([1,6,8].includes(row.commandType)){prefix.push({...row});continue;}
    if(row.commandType===2&&row.side===0&&battleVersion>=6){
      if(row.actionType===undefined)return {complete:false,reason:'manual-antenna-type-unresolved',index:i,prefix};
      integer(row.actionType,'Action内部種別',0,255);
      if(row.actionType===0x37)return done('manual-revival-aborts-special-decision',{aborted:true});
    }
    return done('command-ends-prefix');
  }
  return done('order-exhausted');
}

// Probe on an isolated state. Native remaining phases must be resolved explicitly.
// Never commit the scratch state to the real battle: native replays adopted commands.
function battleProbeSpecialDecision(state,order,options={}) {
  const {battleVersion,battleMode,sideMap,canMove,selectBlow,finishOrder,executeBlow}=options;
  const range=specialDecisionOrderPrefix(order,{battleVersion});
  if(!range.complete)return {complete:false,adopted:false,reason:range.reason};
  if(range.aborted)return {complete:true,adopted:false,reason:range.reason};
  const scratch=structuredClone(state),commands=[],steps=[];
  const pending=reason=>({complete:false,adopted:false,reason,commands:[],steps});
  for(const row of range.prefix){
    if(battleIsEnd(scratch,{battleMode,sideMap}))break;
    if(typeof canMove!=='function')return pending('can-move-unresolved');
    const moving=canMove(scratch,row);if(typeof moving!=='boolean')return pending('can-move-unresolved');
    if(moving&&row.side!==range.prefix[0].side)break;
    let attack=null,choice=null;
    if(moving){
      if(typeof selectBlow!=='function')return pending('blow-selection-unresolved');
      choice=selectBlow(scratch,row);
      if(choice?.complete!==true)return pending('blow-selection-unresolved');
      if(choice.command!==null){
        if(!choice.command)return pending('blow-results-unresolved');
        if(typeof executeBlow==='function'){
          attack=executeBlow(scratch,structuredClone(choice.command),{mode:'execute',row:{...row}});
          if(attack?.complete!==true)return pending('blow-execution-unresolved');
        }else{
          if(!Array.isArray(choice.entries)||choice.entries.some(e=>e.kind!=='blow'))return pending('blow-results-unresolved');
          attack=battleAttackSequence(scratch,choice.entries,{mode:'execute',complete:true,battleVersion,sideMap});
        }
        commands.push(structuredClone(choice.command));
      }
    }
    // Resolve remaining DecideCommand effects or no-command path 92BD84 first.
    if(typeof finishOrder!=='function')return pending('post-command-phases-unresolved');
    const finished=finishOrder(scratch,{row,command:choice?.command??null,attack});
    if(finished?.complete!==true)return pending('post-command-phases-unresolved');
    if(choice?.command)battleFinishCommand(scratch,row,{sideMap});
    steps.push({row:{...row},command:choice?.command??null,attack});
  }
  const ended=battleIsEnd(scratch,{battleMode,sideMap});
  return {complete:true,adopted:ended,commands:ended?commands:[],command:ended?{kind:'special-decision',commands}:null,steps,reason:ended?'scratch-battle-ended':'scratch-battle-not-ended'};
}

// 92B010–92B07C: replay saved COMMANDS against the original battle, not probe HP.
// Return a transaction state only after every command and FinCommand is resolved.
// The caller installs nextState; failed/incomplete replay leaves its state intact.
function battleReplaySpecialDecision(state,probe,{battleVersion,sideMap=[0,1],resolveCommand,finishCommand,executeBlow}={}) {
  const pending=reason=>({complete:false,nextState:null,reason});
  if(probe?.complete!==true||probe.adopted!==true||probe.command?.kind!=='special-decision')return pending('special-decision-not-adopted');
  const commands=probe.command.commands;
  if(!Array.isArray(commands))throw new Error('採用済みコマンド配列が必要です');
  if(commands.length&&((typeof resolveCommand!=='function'&&typeof executeBlow!=='function')||typeof finishCommand!=='function'))return pending('execution-or-fin-command-unresolved');
  const nextState=structuredClone(state),steps=[];
  for(const saved of commands){
    const command=structuredClone(saved);
    // Resolver must use execution RNG/current state, never the probe's entries.
    let attack;
    if(typeof executeBlow==='function'){
      attack=executeBlow(nextState,command,{mode:'execute'});
      if(attack?.complete!==true)return pending('blow-execution-unresolved');
    }else{
      const resolved=resolveCommand(nextState,command,{mode:'execute'});
      if(resolved?.complete!==true||!Array.isArray(resolved.entries)||resolved.entries.some(e=>e.kind!=='blow'))return pending('execution-results-unresolved');
      attack=battleAttackSequence(nextState,resolved.entries,{mode:'execute',complete:true,battleVersion,sideMap});
    }
    const finished=finishCommand(nextState,{command,attack});
    if(finished?.complete!==true)return pending('fin-command-unresolved');
    steps.push({command,attack});
  }
  return {complete:true,nextState,steps,reason:'adopted-commands-replayed'};
}


// CanAddCondition's capacity tail D0F5B8–D0F720, after special UID/resistance checks.
// Return native code 8 (can add), 6 (no improvement), 0 (unsupported mode).
function conditionAddCapacity(state,value,turns) {
  const r=conditionRecord(state.uid),flags=Number(r.words[14]);
  integer(state.current,'現在状態値',r.minimum,r.maximum);integer(value,'付与値',-0x80000000,0x7fffffff);
  integer(state.remainingTurns,'残りターン',0,0xffffffff);integer(turns,'付与ターン',0,15);
  const current=state.current,remaining=state.remainingTurns,mode=(flags>>>18)&7;
  if(current===0)return 8;
  if(mode===1||mode===2){
    if(mode===2&&current===r.maximum)return 6;
    return value<0?(current>r.minimum?8:6):(current<r.maximum-(mode===2?1:0)?8:6);
  }
  if(mode!==3&&mode!==4)return 0;
  if(current!==value)return (mode===3?current<value:current>value)?8:6;
  if(remaining===0)return 6;
  if(turns===0)return 8;
  const timerMode=(flags>>>26)&7;
  if(timerMode===1||timerMode===2)return remaining<(((flags>>>22)&15)||10)?8:6;
  if(timerMode===3)return remaining<turns?8:6;
  if(timerMode===4)return remaining>turns?8:6;
  return 6;
}

// Native CanAddCondition inner gate. Core accessor values must be supplied;
// do not silently substitute stage values for native CoreStage virtual calls.
function conditionAddEligibility(uid,value,turns,{coreState,resistanceValue,haveSkill,canDeadOtherDamage,abilityUpBlocked,isMonster,isDenpa,mainActionUid,maxAp,mainActionElements,attackElementValue,contextFor}={}) {
  const r=conditionRecord(uid),id=Number(r.uid),flags=Number(r.words[14]);
  // Native accepts a signed incoming value, including an equipment-index gate
  // for a linked negative stat change (LotBlowCondition 949818).
  integer(value,'付与値',-0x80000000,0x7fffffff);integer(turns,'付与ターン',0,15);
  const done=(code,reason)=>({complete:true,allowed:code===8,code,reason});
  const pending=reason=>({complete:false,allowed:false,reason});
  if((flags&0x1c0000)===0)return done(3,'condition-not-addable');
  if(value===0)return done(0,'zero-incoming-value');
  // D0F344 jump table: most UIDs enter the common resistance/capacity tail.
  // Only the explicitly dispatched special groups need additional context.
  if([0x87000006,0x8700000A,0x87000052].includes(id))return done(0,'compound-not-addable');
  if([0x87000016,0x87000065,0x87000073,0x8700008F].includes(id)){
    if(typeof contextFor!=='function')return pending('compound-condition-context-unresolved');
    let code=0;
    for(const child of expandClearCondition(uid).uids){
      const evaluated=conditionAddEligibility(child,value,turns,contextFor(child));
      if(!evaluated.complete)return evaluated;
      if(evaluated.code===8)return done(8,'compound-can-add');
      if(evaluated.code>=2&&evaluated.code<=6)code=Math.max(code,evaluated.code);
    }
    return done(code,'compound-no-improvement');
  }
  if([0x87000010,0x87000013,0x87000014,0x87000028,0x8700002D,0x87000083].includes(id)){
    if(value>0){if(typeof abilityUpBlocked!=='boolean')return pending('core-condition-03-unresolved');if(abilityUpBlocked)return done(4,'ability-up-blocked');}
  }else if(id===0x87000019){
    if(typeof haveSkill!=='boolean')return pending('have-skill-unresolved');if(!haveSkill)return done(3,'no-skill');
  }else if(id===0x87000081){
    if(typeof canDeadOtherDamage!=='boolean')return pending('can-dead-other-damage-unresolved');
    if(!canDeadOtherDamage)return done(3,'cannot-die-from-other-damage');
    if(turns===0)return done(8,'instant-ko-bypasses-capacity');
  }else if([0x87000009,0x8700007F].includes(id)){
    if(typeof isMonster!=='boolean')return pending('core-monster-kind-unresolved');
    if(!isMonster)return done(0,'monster-only-condition');
  }else if([0x87000035,0x8700003F,0x87000051,0x87000056,0x8700006E,0x87000089,0x870000C1,0x870000C3].includes(id)){
    if(typeof isDenpa!=='boolean')return pending('core-denpa-kind-unresolved');
    if(isDenpa){
      if(mainActionUid===undefined||maxAp===undefined)return pending('main-action-element-context-unresolved');
      integer(Number(mainActionUid),'MainActionId',0,0xffffffff);integer(maxAp,'最大AP',0,0x7fffffff);
      let matches=false;
      if(Number(mainActionUid)!==0&&maxAp!==0){
        if(!Array.isArray(mainActionElements)||mainActionElements.length!==2)return pending('main-action-element-context-unresolved');
        for(const element of mainActionElements)integer(element,'Action element',0,15);
        matches=mainActionElements.includes((flags>>>4)&15);
      }
      if(!matches){
        if(attackElementValue===undefined)return pending('core-attack-element-unresolved');
        integer(attackElementValue,'攻撃属性状態値',-0x80000000,0x7fffffff);
        if(attackElementValue===0)return done(3,'no-matching-attack-element');
      }
    }
  }else if(id===0x870000B5)return pending('breath-route-out-of-scope');
  if((value<0||(flags&0x1000)!==0)&&Number(r.resistance)!==0){
    if(resistanceValue===undefined)return pending('core-resistance-unresolved');
    integer(resistanceValue,'Core耐性換算値',-0x80000000,0x7fffffff);
    if(resistanceValue===0)return done(5,'resistance-immune');
  }
  if(!coreState||Number(coreState.uid)!==id)return pending('core-condition-state-unresolved');
  const code=conditionAddCapacity(coreState,value,turns);
  return code===0?pending('capacity-mode-unresolved'):done(code,code===8?'can-add':'no-improvement');
}

// Normal type 1C prediction; returns scoring-success rows, not native EC-byte records.
function predictConditionCandidatesWork(state,actor,options={}) {
  const {sideMap,battleMode,battleVersion,implCounter,resolveEligibility}=options;
  const pending=reason=>({complete:false,selectionReady:false,candidates:[],reason});
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const action=actor.antenna?.action;
  if(Number(action?.type)!==0x1c)return pending('not-condition-action');
  if(Number(action.condition_uid)===0x870000B5)return pending('breath-seal-out-of-rankbattle-scope');
  if(battleMode!==0||(battleConditionValue(actor,'8700005F')!==0&&![2,3].includes(options.jackType)))return pending('special-mode-or-jack');
  if(actor.enabled===false||actor.hp<=0||actor.escaped||actor.rental||movementBlockers(actor.conditions).length)return {complete:true,selectionReady:false,candidates:[],reason:'cannot-act'};
  const record=conditionRecord(action.condition_uid),flags=Number(action.flags);
  const repeat=battleActionRepeats(actor,{kind:'antenna',battleVersion,implCounter,apCost:(flags>>>1)&3});
  if(!repeat.apEligible)return {complete:true,selectionReady:false,candidates:[],repeat,reason:repeat.sealed?'antenna-sealed':'insufficient-ap'};
  const generated=battleAntennaTargetCandidates(state,actor,{sideMap,battleMode,jackType:options.jackType??0});
  if(!generated.complete)return {...generated,selectionReady:false};
  if(typeof resolveEligibility!=='function')return pending('native-eligibility-unresolved');
  const candidates=[];
  for(const candidate of generated.candidates){
    const results=[],rawResults=[];
    for(let hitIndex=0;hitIndex<repeat.apEligible;hitIndex++)for(const target of candidate.targets){
      const outer=battleCheckTurnAct(actor,action,{turnNumber:hitIndex+1,canMove:options.canMove});
      if(!outer.complete)return {...pending(outer.reason),candidates};
      if(!outer.allowed)continue;
      const defender=state.parties[target.side].members[target.slot];
      // The callback must include CheckTurnAct/CanHitAction and UID-specific checks.
      const gate=resolveEligibility({actor,defender,action,hitIndex,candidate});
      if(gate?.complete!==true||typeof gate.allowed!=='boolean')return {...pending('native-eligibility-unresolved'),candidates};
      if(!gate.allowed)continue;
      if(typeof options.coreFor==='function'){
        const generated=battleGenerateConditionAntennaResult(state,actor,defender,{battleVersion,turnParameter:hitIndex,coreFor:options.coreFor,jackType:options.jackType??0,mode:'predict'});
        if(!generated.complete)return {...pending(generated.reason),candidates};
        rawResults.push(...generated.results.map(row=>({...row,hitIndex})));
        for(const row of generated.results)if(row.type===2)results.push({...row,kind:'condition',actionUid:action.action_uid,source:{side:actor.side,slot:actor.slot},target:{...target},hitIndex,conditionUid:record.uid,value:action.value,turns:action.turn_min});
        continue;
      }

      if(gate.conditionContext!==undefined){
        const inner=conditionAddEligibility(record.uid,action.value,action.turn_min,gate.conditionContext);
        if(!inner.complete)return {...pending(inner.reason),candidates};
        if(!inner.allowed)continue;
      }
      // GetResultConditionAdd 94A078: this check is not bypassed by target marking.
      if((flags&16)&&battleConditionValue(defender,'870000C6')!==0)continue;
      // Only request the shared capacity tail when the caller's native path uses it.
      if(gate.checkCapacity===true){
        const existing=defender.conditions.find(c=>Number(c.uid)===Number(record.uid))??conditionState(record.uid);
        const code=conditionAddCapacity(existing,action.value,action.turn_min);
        if(code===0)return {...pending('capacity-mode-unresolved'),candidates};
        if(code!==8)continue;
      }
      // seed=0 prediction skips the probability roll. Do not threshold A here.
      results.push({type:2,kind:'condition',actionUid:action.action_uid,source:{side:actor.side,slot:actor.slot},target:{...target},hitIndex,conditionUid:record.uid,value:action.value,turns:action.turn_min});
    }
    const evaluation=scoreAntennaPrediction(state,actor,action,results,options);
    if(!evaluation.complete)return {...pending(evaluation.reason),candidates};
    candidates.push({...candidate,...evaluation,targets:candidate.targets,scoredTargets:evaluation.targets,results,rawResults,selectionReady:false});
  }
  return {complete:true,scope:'condition-scoring-result-prediction',selectionReady:false,candidates,repeat};
}

// Direct prediction calls receive an isolated working battle, just like the
// common antenna entry. Provider failures must not publish partial state writes.
function battlePredictConditionCandidates(state,actor,options={}){
 let location;
 state.parties.forEach((party,side)=>{const slot=party.members.indexOf(actor);if(slot!==-1)location={side,slot};});
 if(!location)throw Error("戦闘内の使用者が必要です");
 const work=structuredClone(state);
 return predictConditionCandidatesWork(work,work.parties[location.side].members[location.slot],options);
}


// CoreStage::HaveSkill D19674. coreKindFlags is the native word at +888.
function battleHaveSkill(actor) {
  if(typeof actor.haveSkill==='boolean')return {complete:true,value:actor.haveSkill};
  const kind=actor.coreKindFlags??actor.coreKind??(actor.accessorKind===undefined?(actor.registration?(actor.side===1?5:1):undefined):coreKindForAccessor(actor.accessorKind));
  if(kind===undefined)return {complete:false,reason:'core-kind-flags-unresolved'};
  integer(kind,'Core+888',0,0xffffffff);
  if((kind&0xfffffff9)===0)return {complete:true,value:false};
  const reference=battleMainActionReference(actor);
  if(!reference.complete)return reference;
  const uid=reference.uid;
  integer(Number(uid),'MainActionId',0,0xffffffff);
  return {complete:true,value:![0,0x8602009A].includes(Number(uid))};
}

// Ordinary registered actor / non-item CheckTurnAct. Target eligibility is separate.
function battleCheckTurnAct(actor,action,{turnNumber=1,itemUid=0,canMove}={}) {
  integer(turnNumber,'1始まりのTurn番号',1,0xffff);integer(itemUid,'Turn+2C',0,0xffffffff);
  const done=(code,reason)=>({complete:true,allowed:code===6,code,reason});
  if(actor.enabled===false||actor.hp<=0||actor.escaped)return done(0,'inactive-source');
  const flags=Number(action.flags);integer(flags,'Action flags',0,0xffffffff);
  if(!(flags&1)){
    // Registered simulator actors use the existing five-state CanMove model.
    const moving=canMove??(actor.registration?!movementBlockers(actor.conditions).length:undefined);
    if(typeof moving!=='boolean')return {complete:false,allowed:false,reason:'can-move-unresolved'};
    if(!moving)return done(1,'cannot-move');
  }
  if(itemUid!==0)return {complete:false,allowed:false,reason:'item-route-not-supported'};
  integer(actor.ap,'現在AP',0,0x7fffffff);
  const apRequired=((flags>>>1)&3)*turnNumber;
  if(actor.ap<apRequired)return done(2,'insufficient-ap');
  if(flags&32)return {complete:false,allowed:false,reason:'breath-route-out-of-scope'};
  if(battleConditionValue(actor,'87000019')!==0){
    const skill=battleHaveSkill(actor);if(!skill.complete)return {...skill,allowed:false};
    if(skill.value){
      const reference=battleMainActionReference(actor);
      if(!reference.complete)return {...reference,allowed:false};
      const main=reference.uid;
      if(Number(main)===Number(action.action_uid))return done(5,'antenna-sealed');
    }
  }
  return {...done(6,'turn-act-eligible'),apRequired};
}


// CanRemoveCondition D0F724. states must represent native Core conditions.
function conditionRemoveEligibility(states,uid,ally) {
  if(typeof ally!=='boolean'||!Array.isArray(states))throw new Error('Core状態配列と対象陣営が必要です');
  const id=typeof uid==='string'&&/^[0-9a-f]{8}$/i.test(uid)?Number.parseInt(uid,16):Number(uid),compound=[0x87000006,0x8700000A,0x87000016,0x87000052,0x87000073,0x8700008F].includes(id);
  // CanRemoveCondition D0F77C–D0F8B8 deliberately does not expand 0x65.
  if(id===0)return {complete:true,allowed:false,code:0};
  const records=compound?expandClearCondition(uid).uids.map(conditionRecord):[conditionRecord(uid)];
  let code=compound?0:6;
  for(const r of records){
    const s=states.find(c=>Number(c.uid)===Number(r.uid));
    const diff=s?s.current-s.base:0,harmful=(Number(r.words[14])&0x1000)!==0;
    if(diff!==0&&(ally===harmful?diff>0:diff<0))return {complete:true,allowed:true,code:8};
    code=Math.max(code,6);
  }
  return {complete:true,allowed:false,code};
}

// CanHitAction D0F04C; result-stage hit/reflection/condition lottery is separate.
function battleTargetEligibility(target,action,{statusVersion,includeDead=false,coreStates,conditionEligibility,isMonster}={}) {
  integer(statusVersion,'StatusVersion',1,9999);
  if(typeof includeDead!=='boolean')throw new Error('死亡検査省略はbooleanです');
  const result=(code,reason)=>({complete:true,code,allowed:code===7||code===8,reason});
  if(!target||target.enabled===false)return result(0,'disabled-target');
  if(target.escaped)return result(statusVersion>=2?2:0,'escaped-target');
  const flags=Number(action.flags);integer(flags,'Action flags',0,0xffffffff);
  if(((flags>>>8)&15)!==11&&target.rental)return result(0,'rental-target');
  const type=Number(action.type);integer(type,'Action type',0,255);
  if(!includeDead&&type!==0x37&&target.hp<=0)return result(1,'dead-target');
  if(type===0)return result(8,'empty-action');
  if(type===1)return result(3,'no-battle-action');
  if([0x15,0x17,0x99].includes(type))return result(7,'attack-target');
  if(type===0x37)return result(target.hp<=0?8:6,target.hp<=0?'revivable':'alive-target');
  if(type===0x35||type===0x9b){
    if(!coreStates)return {complete:false,allowed:false,reason:'core-conditions-unresolved'};
    return conditionRemoveEligibility(coreStates,action.condition_uid,((flags>>>6)&3)===2);
  }
  if([0x32,0x9c,0x9e].includes(type)){
    integer(target.hp,'現在HP',0,0x7fffffff);integer(target.initialStats.hp,'最大HP',1,0x7fffffff);
    return result(target.hp<target.initialStats.hp?8:6,target.hp<target.initialStats.hp?'hp-missing':'hp-full');
  }
  if(type===0x34||type===0x9f){
    integer(target.ap,'現在AP',0,0x7fffffff);integer(target.initialStats.ap,'最大AP',0,0x7fffffff);
    return result(target.ap<target.initialStats.ap?8:6,target.ap<target.initialStats.ap?'ap-missing':'ap-full');
  }
  if([0x1d,0x1e,0x1f,0x3c].includes(type)){
    if(typeof isMonster!=='boolean')return {complete:false,allowed:false,reason:'core-monster-kind-unresolved'};
    return result(isMonster?8:0,'monster-only');
  }
  if(type===0x20||[0x96,0x97,0x98].includes(type)){
    if(!coreStates)return {complete:false,allowed:false,reason:'core-conditions-unresolved'};
    const uid=type===0x20?0x87000057:Number(action.condition_uid);
    const current=coreStates.find(s=>Number(s.uid)===uid)?.current??0;
    if(type===0x20)return result(current===0?8:4,'condition-57');
    integer(action.value,'Action value',-0x80000000,0x7fffffff);
    return result(current!==0&&(current>0?action.value>0:action.value<0)?8:4,'matching-condition-sign');
  }
  if([0x1c,0x9d,0x9a].includes(type)){
    if(typeof conditionEligibility!=='function')return {complete:false,allowed:false,reason:'condition-add-context-unresolved'};
    const incoming=Number(action.value);integer(incoming,'Action value',-0x80000000,0x7fffffff);
    // CMP/CSINC uses unsigned HI: negative signed values are retained.
    const value=type===0x9a&&(incoming>>>0)<=1?1:incoming;
    const gate=conditionEligibility(target,action.condition_uid,value,(flags>>>12)&15);
    if(gate?.complete!==true)return {complete:false,allowed:false,reason:gate?.reason??'condition-add-context-unresolved'};
    integer(gate.code,'CanAddCondition result',0,8);
    return result(gate.code,'condition-add');
  }
  // 0x36 dispatches to a dedicated helper. Other entries in the native
  // 160-byte jump table point to D0F0C8 (code 0), not an unresolved gate.
  if(type!==0x36)return result(0,'unsupported-native-action-type');
  if(!coreStates)return {complete:false,allowed:false,reason:'core-conditions-unresolved'};
  let code=0;
  for(const uid of plusConditionUids()){
    const gate=conditionRemoveEligibility(coreStates,uid,false);
    if(gate.code===8)return result(8,'removable-plus-condition');
    if(gate.code>=2&&gate.code<=6)code=Math.max(code,gate.code);
  }
  return result(code,'no-removable-plus-condition');
}

// InitializeSubBaseUid creates these concrete accessors and writes +888.
function coreKindForAccessor(accessorKind) {
  if(accessorKind==='box')return 1;
  if(accessorKind==='comm')return 5;
  if(accessorKind==='enemy-denpa')return 7;
  throw new Error('監査済みの具体的アクセサ種別が必要です');
}


// GetResultConditionEnd 94B150–94B438. Network antenna path (Turn+2C=0).
// Typed effect result only; outer GetResult retention and AP belong to the caller.
function cureAntennaResult(action,{battleVersion,mode='execute',canHitCode,turnParameter=0,randomContext,turnFlag=false}={}){
 if(![0x35,0x36].includes(Number(action?.type)))throw Error('解除アンテナActionが必要です');
 integer(battleVersion,'BattleVersion',1,9999);integer(turnParameter,'Turn+1C',0,0xffffffff);
 if(!['execute','predict'].includes(mode))throw Error('Invalid cure mode');
 integer(Number(action.flags),'Action flags',0,0xffffffff);
 if(mode==='predict'&&battleVersion<2)throw Error('旧版の解除予測乱数経路は未接続です');
 if(Number(action.type)===0x35&&Number(action.condition_uid)===0)return null;
 if(typeof turnFlag!=='boolean')throw Error('Turn+2C must be boolean');
 const displus=Number(action.type)===0x36;
 const row={...(displus?{conditionCode:0}:{}),kind:'cure',actionUid:action.action_uid,conditionUid:action.condition_uid,trace:[]};
 if(mode==='predict'&&battleVersion>=2)return {...row,type:2,conditionValue:1,reason:'prediction-no-lottery'};
 if(mode==='execute'){
  integer(canHitCode,'CanHitAction',0,8);
  if(canHitCode!==8){
   // ConditionEnd 94B198..94B1D4 / DisPlus 94B780..94B7BC: escaped special Turn retains type5.
   if(canHitCode===2&&turnFlag&&battleVersion>=3)return {...row,type:5,conditionCode:16,reason:'escaped-target'};
   if(![1,6].includes(canHitCode))return null;
   const type=turnParameter>1||(Number(action.flags)&8)!==0||(turnFlag&&battleVersion>=3)?5:3;
   return {...row,type,conditionCode:16,reason:canHitCode===1?'dead-target':'nothing-to-clear'};
  }
 }
 // GetResultDisPlus 94B730..94B75C has no success lottery.
 if(Number(action.type)===0x36)return {...row,type:2,conditionValue:1,reason:'displus-success'};
 const A=(Number(action.flags)>>>20)&31;
 // Native unsigned (A-1)>28: 0,30,31 all bypass this lottery.
 if(A>=1&&A<=29){
  const seed=battleRandomSeed({...randomContext,battleVersion,turnParameter,salt:794});
  const raw=createGsRandom(seed).nextU32(),roll=raw%30;
  row.trace.push({label:'cure-success',seed,raw,roll,denominator:30,A});
  if(roll>=A)return {...row,type:turnParameter>=2&&battleVersion<2?5:3,reason:'lottery-failed'};
 }
 return {...row,type:2,conditionValue:1,reason:'cure-success'};
}

// Resolve one target's effect, without charging AP or publishing outer counters.
// A full command groups all targets, finalizes the result list, then books it once.
function battleResolveCureAntennaTarget(state,source,target,{battleVersion,turnParameter=0,nativeRandomState,coreFor,sideMap}={}){
 if(!state.parties.some(p=>p.members.includes(source))||!state.parties.some(p=>p.members.includes(target)))throw Error('戦闘内の使用者・解除対象が必要です');
 const action=source.antenna?.action;
 if(![0x35,0x36].includes(Number(action?.type)))throw Error('解除アンテナActionが必要です');
 const gate=battleResolvedTargetEligibility(state,target,action,{coreFor});
 if(!gate.complete)return {complete:false,reason:gate.reason};
 const result=cureAntennaResult(action,{battleVersion,turnParameter,canHitCode:gate.code,
  randomContext:{...nativeRandomState,sourceJoinSeed:source.joinRandSeed,targetJoinSeed:target.joinRandSeed}});
 if(!result)return {complete:true,results:[],scope:'cure-target-effect'};
 const record={...result,source:{side:source.side,slot:source.slot},target:{side:target.side,slot:target.slot}};
 const applied=battleApplyCureResult(state,target,action,record,{sideMap,canClear:(actor,uid)=>battleConditionWriteFlag(actor,uid,{coreFor})});
 if(!applied.complete)return applied;
 return {complete:true,results:[record],applied,scope:'cure-target-effect'};
}


function predictCureCandidatesWork(state,actor,options={}) {
  const {battleVersion,battleMode,sideMap,implCounter,coreStatesFor}=options;
  const pending=reason=>({complete:false,selectionReady:false,candidates:[],reason});
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const action=actor.antenna?.action;
  if(Number(action?.type)!==0x35||battleMode!==0||battleVersion<2)return pending('unsupported-cure-route');
  const generated=battleAntennaTargetCandidates(state,actor,{sideMap,battleMode,jackType:options.jackType??0});
  if(!generated.complete)return {...generated,selectionReady:false};
  const repeat=battleActionRepeats(actor,{kind:'antenna',battleVersion,implCounter,apCost:(Number(action.flags)>>>1)&3});
  const candidates=[];
  for(const candidate of generated.candidates){
    const results=[];
    for(let hitIndex=0;hitIndex<repeat.apEligible;hitIndex++){
      const outer=battleCheckTurnAct(actor,action,{turnNumber:hitIndex+1,canMove:options.canMove});
      if(!outer.complete)return {...pending(outer.reason),candidates};
      if(!outer.allowed)continue;
      for(const target of candidate.targets){
        const defender=state.parties[target.side].members[target.slot];
        const gate=typeof options.resolveEligibility==='function'
          ?options.resolveEligibility({actor,defender,action,hitIndex,candidate})
          :battleTargetEligibility(defender,action,{statusVersion:state.statusVersion,coreStates:coreStatesFor?.(defender)});
        if(!gate.complete)return {...pending(gate.reason),candidates};
        if(gate.allowed)results.push({...cureAntennaResult(action,{battleVersion,mode:'predict',turnParameter:hitIndex}),target:{...target},source:{side:actor.side,slot:actor.slot},hitIndex});
      }
    }
    const score=scoreCurePrediction(state,action,results,options);
    candidates.push({...candidate,...score,targets:candidate.targets,scoredTargets:score.targets,results,selectionReady:false});
  }
  return {complete:true,selectionReady:false,scope:'cure-scoring-results',candidates,repeat};
}

// Direct prediction calls receive an isolated working battle, just like the
// common antenna entry. Provider failures must not publish partial state writes.
function battlePredictCureCandidates(state,actor,options={}){
 let location;
 state.parties.forEach((party,side)=>{const slot=party.members.indexOf(actor);if(slot!==-1)location={side,slot};});
 if(!location)throw Error("戦闘内の使用者が必要です");
 const work=structuredClone(state);
 return predictCureCandidatesWork(work,work.parties[location.side].members[location.slot],options);
}


// Common read-only prediction entry. Completion is scoped, not execution permission.
function predictAntennaCandidatesWork(state,actor,options={}) {
  if(typeof options.coreFor==='function')options={...options,
    coreStatesFor:options.coreStatesFor??(target=>options.coreFor(target)?.conditions),
    resolveEligibility:options.resolveEligibility??(({defender,action})=>battleResolvedTargetEligibility(state,defender,action,{coreFor:options.coreFor}))};
  if(!options.targetInfo&&typeof options.riskContextFor==='function')options={...options,targetInfo:target=>{
    const info=battleRiskTargetInfo(target,options.riskContextFor(target));
    if(!info.complete)throw new Error(info.reason);
    return info;
  }};
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const action=actor.antenna?.action,type=Number(action?.type);
  const empty=reason=>({complete:true,selectionReady:false,candidates:[],bestCandidate:null,reason});
  if(!action)return empty('no-antenna');
  if(type===1)return empty('no-battle-command');
  const predict=type===0x17?battlePredictElementalCandidates:[0x32,0x37].includes(type)?battlePredictHealCandidates:type===0x1c?battlePredictConditionCandidates:type===0x35?battlePredictCureCandidates:null;
  if(!predict)return {complete:false,selectionReady:false,candidates:[],bestCandidate:null,reason:'unknown-antenna-type'};
  const prediction=predict(state,actor,options);
  if(!prediction.complete)return {...prediction,bestCandidate:null};
  const candidates=prediction.candidates.map(candidate=>{
    const seen=new Set();let currentHpSum=0,maxHpSum=0;
    for(const target of candidate.targets){
      integer(target.side,'対象側',0,1);integer(target.slot,'対象位置',0,7);
      const key=`${target.side}:${target.slot}`;
      if(seen.has(key))throw new Error('候補内の対象重複');seen.add(key);
      const member=state.parties[target.side].members[target.slot];
      if(!member)throw new Error('候補対象が存在しません');
      integer(member.hp,'対象HP',0,0x7fffffff);integer(member.initialStats.hp,'対象最大HP',1,0x7fffffff);
      currentHpSum+=member.hp;maxHpSum+=member.initialStats.hp;
    }
    return {...candidate,currentHpSum,maxHpSum,selectionReady:false};
  });
  const comparison=selectAutoCandidate(candidates);
  return {...prediction,candidates,bestCandidate:comparison.selected,comparisonReason:comparison.reason,policy:antennaAdoptionPolicy(action),selectionReady:false,scope:'antenna-prediction-and-comparison'};
}

// Providers receive the same isolated battle as the prediction engines.
// Errors or incidental writes cannot publish changes to the input state.
function battlePredictAntennaCandidates(state,actor,options={}){
 let location;
 state.parties.forEach((party,side)=>{const slot=party.members.indexOf(actor);if(slot!==-1)location={side,slot};});
 if(!location)throw Error('戦闘内の使用者が必要です');
 const work=structuredClone(state);
 return predictAntennaCandidatesWork(work,work.parties[location.side].members[location.slot],options);
}


// Native candidate masks/order and physical hit resolution remain explicit inputs.
// PreUse predictions never change the real HP, AP, conditions or decision.
function predictBlowCandidatesWork(state,actor,options={}) {
  const {action,candidateSet,battleVersion,implCounter,resolveEntry,targetInfo,previousMatches}=options;
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const pending=reason=>({complete:false,selectionReady:false,candidates:[],bestCandidate:null,reason});
  if(Number(action?.type)!==0x15)return pending('blow-action-unresolved');
  if(actor.rental||battleConditionValue(actor,'0x8700005F')!==0)return pending('special-source-route');
  if(candidateSet?.complete!==true||!Array.isArray(candidateSet.candidates))return pending('blow-masks-and-order-unresolved');
  if(typeof resolveEntry!=='function'||typeof targetInfo!=='function'||typeof previousMatches!=='function')return pending('blow-hit-or-scoring-context-unresolved');
  const repeat=battleActionRepeats(actor,{kind:'blow',battleVersion,implCounter});
  const candidates=[],source={side:actor.side,slot:actor.slot};
  for(const candidate of candidateSet.candidates){
    if(!Array.isArray(candidate.targets))throw new Error('元の候補maskに対応する対象配列が必要です');
    const seen=new Set();let currentHpSum=0,maxHpSum=0;
    for(const ref of candidate.targets){
      integer(ref.side,'対象側',0,1);integer(ref.slot,'対象位置',0,7);
      const key=`${ref.side}:${ref.slot}`,target=state.parties[ref.side].members[ref.slot];
      if(seen.has(key)||!target)throw new Error('候補対象の重複または欠落');seen.add(key);
      currentHpSum+=target.hp;maxHpSum+=target.initialStats.hp;
    }
    const entries=[];
    for(let hitIndex=0;hitIndex<repeat.generated;hitIndex++){
      const outer=battleCheckTurnAct(actor,action,{turnNumber:hitIndex+1,canMove:options.canMove});
      if(!outer.complete)return pending(outer.reason);
      if(!outer.allowed)continue;
      for(const ref of candidate.targets){
        const defender=state.parties[ref.side].members[ref.slot];
        const gate=battleTargetEligibility(defender,action,{statusVersion:state.statusVersion});
        if(!gate.complete)return pending(gate.reason);
        if(!gate.allowed)continue;
        const resolved=resolveEntry({actor,defender,candidate,hitIndex,mode:'predict'});
        if(resolved?.complete!==true)return pending('blow-hit-path-unresolved');
        if(resolved.skip===true)continue;
        entries.push({...resolved,source:{...source},target:{...ref},kind:'blow'});
      }
    }
    const prediction=battleAttackSequence(state,entries,{mode:'predict',complete:true,battleVersion});
    const evaluation=scoreBlowPrediction(state,prediction.results,{targetInfo,previousMatches:r=>previousMatches(r,candidate)});
    candidates.push({...candidate,...evaluation,targets:candidate.targets,scoredTargets:evaluation.targets,currentHpSum,maxHpSum,prediction,selectionReady:false});
  }
  const comparison=selectAutoCandidate(candidates);
  return {complete:true,selectionReady:false,candidates,bestCandidate:comparison.selected,comparisonReason:comparison.reason,repeat,scope:'blow-prediction-and-comparison'};
}

// Providers receive the same isolated battle as the prediction engines.
// Errors or incidental writes cannot publish changes to the input state.
function battlePredictBlowCandidates(state,actor,options={}){
 let location;
 state.parties.forEach((party,side)=>{const slot=party.members.indexOf(actor);if(slot!==-1)location={side,slot};});
 if(!location)throw Error('戦闘内の使用者が必要です');
 const work=structuredClone(state);
 return predictBlowCandidatesWork(work,work.parties[location.side].members[location.slot],options);
}


// CreateHelper command 6, ordinary movable non-rental/non-jacked actor only.
// Lazy providers must return fully resolved candidates, never promote preview data.
function planAutomaticTurnWork(state,actor,options={}) {
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const trace=[],pending=reason=>({complete:false,selected:null,reason,trace});
  if(actor.rental||battleConditionValue(actor,'0x8700005F')!==0)return pending('special-source-route');
  if(actor.enabled===false||actor.hp<=0||actor.escaped||options.canMove!==true)return pending('normal-movable-source-required');
  integer(actor.ap,'現在AP',0,0x7fffffff);
  const getBlow=()=>{trace.push('blow');return options.selectBlow?.(state,actor);};
  const fallback=reason=>{
    const blow=getBlow();
    if(blow?.complete!==true||blow.selectionReady!==true)return pending('blow-selection-unresolved');
    return {complete:true,selected:blow,reason,trace};
  };
  // 92A560–92A598: bypass both SpecialDecision and main antenna evaluation.
  if(actor.ap===0)return fallback('zero-ap-blow');
  if(battleConditionValue(actor,'0x87000019')!==0)return fallback('sealed-blow');
  trace.push('special-decision');
  if(!options.order)return pending('special-order-unresolved');
  const special=battleProbeSpecialDecision(state,options.order,options.special);
  if(!special.complete)return pending(special.reason);
  if(special.adopted)return {complete:true,selected:special.command,special,reason:'special-decision',trace};
  const action=actor.antenna?.action;
  if(!action)return pending('main-action-unresolved');
  if(antennaAdoptionPolicy(action)==='no-battle-command')return fallback('no-battle-command');
  trace.push('antenna-eligibility');
  const eligibility=typeof options.antennaEligibility==='function'?options.antennaEligibility(state,actor,action):
    action.flags===undefined?undefined:battleCheckTurnAct(actor,action,{turnNumber:1,canMove:options.canMove});
  if(eligibility?.complete!==true||typeof eligibility.allowed!=='boolean')return pending('action-eligibility-unresolved');
  if(!eligibility.allowed)return fallback('antenna-unavailable');
  trace.push('antenna');
  const antenna=options.selectAntenna?.(state,actor);
  if(antenna?.complete!==true||antenna.selectionReady!==true)return pending('antenna-candidate-unresolved');
  integer(antenna.score,'アンテナ点',0,0xffffffff);
  const blow=antenna.score===0||antennaAdoptionPolicy(action)==='compare-blow'?getBlow():undefined;
  return {...decideAntennaAdoption(action,{antenna,blow,eligibility,specialDecision:special}),trace};
}

// Planning cannot publish scratch HP/AP, counters or RNG state. Providers see
// the same isolated battle throughout the decision, including SpecialDecision.
// Providers must still not mutate external objects captured by their closures.
function battlePlanAutomaticTurn(state,actor,options={}) {
  let location;
  state.parties.forEach((party,side)=>{
    const slot=party.members.indexOf(actor);
    if(slot!==-1)location={side,slot};
  });
  if(!location)throw new Error('戦闘内の使用者が必要です');
  const work=structuredClone(state);
  return planAutomaticTurnWork(work,work.parties[location.side].members[location.slot],options);
}

// Complete command executors must include all hit results, reactions and FinCommand.
// No global RNG or external state may be mutated by providers.
function battleRunAutomaticTurn(state,actor,options={}) {
  const decision=battlePlanAutomaticTurn(state,actor,options);
  if(!decision.complete)return {...decision,nextState:null};
  if(decision.special){
    const replay=battleReplaySpecialDecision(state,decision.special,options.execution);
    return {...replay,decision};
  }
  if(typeof options.executeCommand!=='function')return {complete:false,nextState:null,decision,reason:'command-executor-unresolved'};
  const nextState=structuredClone(state),command=structuredClone(decision.selected);
  const executed=options.executeCommand(nextState,command,{mode:'execute',source:{side:actor.side,slot:actor.slot}});
  if(executed?.complete!==true)return {complete:false,nextState:null,decision,reason:'command-execution-unresolved'};
  return {complete:true,nextState,decision,execution:executed,reason:'automatic-command-executed'};
}


// FinCommand 93CA68 / Impl::FinCommand 93C9E0.
// Only writes Impl+290[internalSide*10+slot] = 1. No reactions or RNG.
function battleFinishCommand(state,order,{sideMap}={}) {
  integer(order.side,'内部陣営',0,0xffffffff);integer(order.slot,'内部位置',0,0xffffffff);
  if(order.side>1||order.slot>9)return {complete:true,changed:false,reason:'outside-order-table'};
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw new Error('UI側から内部側へのsideMapが必要です');
  const flags=state.finishedOrders??Array(20).fill(false);
  if(!Array.isArray(flags)||flags.length!==20||flags.some(v=>typeof v!=='boolean'))throw new Error('20件の終了フラグが必要です');
  const index=order.side*10+order.slot,changed=!flags[index];
  flags[index]=true;state.finishedOrders=flags;
  const actor=state.parties[sideMap.indexOf(order.side)].members[order.slot];
  if(actor)actor.processed=true;
  return {complete:true,changed,index};
}


// GetAutoTurnAction 93E77C–93EA20. Null DB_MonsterParameter is a resolved
// absence, not a missing implementation. Do not infer null from absent data.
function battleSelectOtherTurnAction(actor,turnType,{monsterParameter=actor?.monsterParameter,actionFor,canMove}={}){
  integer(turnType,'native TurnType',0,0xffffffff);
  const none=reason=>({complete:true,action:null,reason});
  const pending=reason=>({complete:false,action:null,reason});
  if(!actor||actor.enabled===false||actor.escaped)return none('invalid-source');
  if(monsterParameter===null)return none('no-monster-parameter');
  if(monsterParameter===undefined)return pending('monster-parameter-unresolved');
  const fields=({0:[0x10,9],2:[0x14,19],11:[0x18,29],12:[0x1c,39],4:[0x20,49]})[turnType];
  if(!fields)return none('no-action-for-phase');
  if(!(monsterParameter instanceof Uint8Array)||monsterParameter.byteLength<0x24)throw new Error('MonsterParameterの先頭0x24 byte以上が必要です');
  const data=new DataView(monsterParameter.buffer,monsterParameter.byteOffset,monsterParameter.byteLength);
  const uid=data.getUint32(fields[0],true);
  if(uid===0)return none('empty-auto-action');
  const flags=data.getBigUint64(8,true),shift=BigInt(fields[1]);
  const condition=Number((flags>>shift)&63n),chance=Number((flags>>(shift+6n))&15n)*10;
  const actionUid='0x'+uid.toString(16).padStart(8,'0').toUpperCase();
  if(typeof actionFor!=='function')return pending('auto-action-record-unresolved');
  const record=actionFor(actionUid);
  if(record===null)return none('auto-action-record-absent');
  if(!record)return pending('auto-action-record-unresolved');
  integer(record.type,'Action type',0,255);integer(record.flags,'Action flags',0,0xffffffff);
  // A type-0 action with bit 0 set bypasses CanMove and Jack checks.
  if(!(record.type===0&&(record.flags&1))){
    if(typeof canMove!=='boolean')return pending('native-can-move-unresolved');
    if(!canMove)return none('cannot-move');
    if(!Array.isArray(actor.conditions))return pending('jack-state-unresolved');
    if(battleConditionValue(actor,'0x8700005F')!==0)return none('jacked-source');
  }
  return {complete:true,action:{actionUid,actionFlags:record.flags,condition,chance},reason:'auto-action-selected'};
}

function decodeOtherTurnResult(bytes,{actionType}={}){
  if(!(bytes instanceof Uint8Array)||bytes.length!==0xec)throw new Error('0xEC byteの結果が必要です');
  integer(actionType,'trigger Action type',0,255);
  const r=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
  return {word8:r.getUint32(8,true),word58:r.getInt32(0x58,true),word60:r.getUint32(0x60,true),flags64:r.getUint16(0x64,true),actionType};
}

// CheckOtherTurnHit 943F9C–9441F8: action class and saved result bits.
function checkOtherTurnHit(actor,condition,result){
  integer(condition,'AutoTurnAction condition',0,0xffffffff);
  const done=(allowed,reason)=>({complete:true,allowed,reason});
  if(!actor||result===null)return done(false,'no-trigger-result');
  if(actor.hp===undefined)return {complete:false,allowed:false,reason:'source-death-state-unresolved'};
  integer(actor.hp,'current HP',0,0x7fffffff);
  if(actor.hp===0)return done(false,'dead-reaction-source');
  if(result?.actionType===undefined)return {complete:false,allowed:false,reason:'trigger-action-type-unresolved'};
  integer(result.actionType,'trigger Action type',0,255);
  const allowedType=[2,25].includes(condition)?result.actionType===0x15:[3,26].includes(condition)?result.actionType===0x17:[0x15,0x17].includes(result.actionType);
  if(!allowedType)return done(false,'trigger-action-type-mismatch');
  if([2,3,25,26].includes(condition)){
    if(result.word58===undefined)return {complete:false,allowed:false,reason:'trigger-damage-unresolved'};
    integer(result.word58,'Result+58',-0x80000000,0x7fffffff);
    return done(result.word58>0,'positive-hit-damage');
  }
  if(condition<4||condition>11)return done(false,'not-hit-condition');
  if(result.flags64===undefined)return {complete:false,allowed:false,reason:'trigger-hit-flags-unresolved'};
  integer(result.flags64,'Result+64/+65',0,65535);
  return done((result.flags64&(1<<(condition-3)))!==0,'hit-result-flag');
}

// GetNowPercent D03D2C uses uint64 multiplication, floor and a 100% cap.
function battleHpPercent(actor){
  integer(actor.hp,'current HP',0,0xffffffff);
  integer(actor.initialStats?.hp,'maximum HP',0,0xffffffff);
  if(actor.initialStats.hp===0)return 100;
  const percent=BigInt(actor.hp)*100n/BigInt(actor.initialStats.hp);
  return Number(percent>100n?100n:percent);
}

// Supply only owned/known battle values. In particular, don't replace Impl+8
// with the displayed round or infer unknown boot/reaction counters as zero.
function battleCheckOtherTurnInState(state,actor,autoAction,{sideMap,implCounter,result,actionType}={}){
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw new Error('sideMapが必要です');
  const members=state.parties[sideMap.indexOf(1)].members;
  const internalSide1Alive=members.filter(a=>a&&a.enabled!==false&&a.hp>0&&!a.escaped&&!a.rental).length;
  return battleCheckOtherTurn(actor,autoAction,{implCounter,result:result instanceof Uint8Array?decodeOtherTurnResult(result,{actionType}):result,
    hpPercent:battleHpPercent(actor),internalSide1Alive,bootOnce:actor.bootOnce,
    successfulSpecialCount:state.resultBookkeeping?.successfulSpecialCount,reactionFlags:state.resultBookkeeping?.reactionFlags});
}

// Shared selection -> prerequisite -> lottery path. An allowed action still
// needs target generation and the common executor; it is not an executed turn.
function battlePlanOtherTurn(state,actor,turnType,options={}){
  if(!state.parties.some(p=>p.members.includes(actor)))throw new Error('戦闘内の使用者が必要です');
  const selected=battleSelectOtherTurnAction(actor,turnType,options);
  if(!selected.complete||selected.action===null)return {...selected,allowed:false};
  const gate=battleCheckOtherTurnInState(state,actor,selected.action,options);
  return {...gate,action:gate.complete&&gate.allowed?selected.action:null,selection:selected,scope:'other-turn-selection-and-gate'};
}

// CheckOtherTurn 942C68–942D50, local MT. resultWord8 is Result+8, NOT Impl+C.
function otherTurnLottery({joinRandSeed,implCounter,condition,chance,resultWord8=null}) {
  for(const [name,value] of Object.entries({joinRandSeed,implCounter,condition,chance}))integer(value,name,0,0xffffffff);
  if(resultWord8!==null)integer(resultWord8,'Result+8',0,0xffffffff);
  const seed=(Math.imul(joinRandSeed,953)+implCounter+condition+751+(resultWord8===null?0:Math.imul(resultWord8,123)))>>>0;
  const random=createGsRandom(seed),raw=random.nextU32(),roll=raw%100;
  return {allowed:chance>roll,seed,normalizedSeed:random.seed,raw,roll};
}

// All CheckOtherTurn conditions 0..26. No automatic revival assumed.
// Caller supplies native result words and GetNowPercent; unknown fields stay pending.
function battleCheckOtherTurn(actor,autoAction,context={}) {
  const done=(allowed,reason,extra={})=>({complete:true,allowed,reason,...extra});
  const pending=reason=>({complete:false,allowed:false,reason});
  if(!actor)return done(false,'missing-source');
  if(!autoAction||autoAction.actionFlags===undefined)return pending('auto-action-record-unresolved');
  const {actionFlags,condition,chance}=autoAction;
  integer(actionFlags,'Action+1C',0,0xffffffff);integer(condition,'AutoTurnAction+4',0,0xffffffff);
  integer(actor.ap,'現在AP',0,0x7fffffff);
  if(actor.ap<((actionFlags>>>1)&3))return done(false,'insufficient-ap');
  if(condition>26)return done(false,'unknown-condition-number');
  if(condition===0)return done(true,'unconditional');
  integer(chance,'AutoTurnAction+8',0,0xffffffff);
  if(condition===15){
    if(context.hpPercent===undefined)return pending('native-hp-percent-unresolved');
    integer(context.hpPercent,'GetNowPercent',0,0xffffffff);
    return done(context.hpPercent<=Math.min(chance,100),'hp-threshold');
  }
  if(condition===12){
    if(context.result===null)return done(false,'no-trigger-result');
    if(context.result?.word60===undefined)return pending('result-death-code-unresolved');
    integer(context.result.word60,'Result+60',0,0xffffffff);
    if(context.result.word60!==1)return done(false,'result-not-death');
  }
  if([13,14].includes(condition)){
    if(context.internalSide1Alive===undefined)return pending('internal-side1-alive-count-unresolved');
    integer(context.internalSide1Alive,'GetAliveNum(1)',0,10);
    if(!(condition===13?context.internalSide1Alive>1:context.internalSide1Alive===1))return done(false,'alive-count-condition');
  }
  if([16,17].includes(condition)){
    if(context.hpPercent===undefined)return pending('native-hp-percent-unresolved');
    integer(context.hpPercent,'GetNowPercent',0,0xffffffff);
    if(context.hpPercent>=(condition===16?51:26))return done(false,'hp-threshold');
  }
  if(condition===18){
    if(context.successfulSpecialCount===undefined)return pending('Impl+2D8-unresolved');
    integer(context.successfulSpecialCount,'Impl+2D8',0,0xffffffff);
    if(context.successfulSpecialCount===0)return done(false,'no-special-success');
  }
  if(condition===19){
    if(typeof context.bootOnce!=='boolean')return pending('boot-once-unresolved');
    if(context.bootOnce)return done(false,'already-booted');
  }
  if(condition>=20&&condition<=23){
    if(context.reactionFlags===undefined)return pending('Impl+2DC-unresolved');
    integer(context.reactionFlags,'Impl+2DC',0,0xffffffff);
    if(context.reactionFlags&(1<<(condition-20)))return done(false,'reaction-flag-already-set');
  }
  if(condition>=24){
    if(!Array.isArray(actor.conditions))return pending('source-condition-values-unresolved');
    if(battleConditionValue(actor,'0x8700007F')===0&&battleConditionValue(actor,'0x87000009')===0)return done(false,'source-condition-absent');
  }
  if(condition>=2&&condition<=11||condition>=25){
    const hit=checkOtherTurnHit(actor,condition,context.result);
    if(!hit.complete||!hit.allowed)return hit;
  }
  if(context.result===undefined||context.result!==null&&context.result.word8===undefined)return pending('trigger-result-unresolved');
  if(actor.joinRandSeed===undefined||context.implCounter===undefined)return pending('reaction-seed-unresolved');
  const lottery=otherTurnLottery({joinRandSeed:actor.joinRandSeed,implCounter:context.implCounter,condition,chance,resultWord8:context.result===null?null:context.result.word8});
  return done(lottery.allowed,'reaction-lottery',{lottery});
}

