// Core GetRisk / IsTopPriorityRisk. Inputs belong to the referenced accessor.
function coreAntennaRisk({groupUid,level,ap}) {
  integer(level,'Core level',0,9999);integer(ap,'Core GetAP+8',0,0x7fffffff);
  const uid=ap===0?0x5006E87C:Number(groupUid),row=riskGroups.find(r=>Number(r.uid)===uid);
  if(!row)throw new Error('危険度のSkillGroupが未解決です');
  const packed=row.packed;
  return {risk:((packed>>>1)&1023)*10+level,topPriority:(packed&1)!==0};
}

// D1C8B8: mask is 0xFFF8, deliberately not ~7. Top priority always uses +890.
function battleRiskTargetInfo(actor,{stageWord880,coreKind,originalCore,canMove}={}) {
  if(stageWord880===undefined||coreKind===undefined||!originalCore||typeof canMove!=='boolean')return {complete:false,reason:'risk-accessor-context-unresolved'};
  integer(stageWord880,'Stage+880',0,0xffffffff);integer(coreKind,'Stage+888',0,0xffffffff);
  const original=coreAntennaRisk(originalCore);
  const useOriginal=stageUsesOriginalCore(stageWord880,coreKind);
  const base=useOriginal?original:coreAntennaRisk({groupUid:actor.antenna?.groupUid,level:actor.level,ap:actor.ap});
  const risk=canMove?base.risk:Math.trunc(base.risk*80/100);
  return {complete:true,risk,topPriority:original.topPriority,targetFlag:battleConditionValue(actor,'0x870000AD')!==0,attack:battleCurrentStats(actor).atk,riskSource:useOriginal?'original-core':'stage-core'};
}

// Registered enemies use OriginalCore; explicit native context takes priority.
function registeredPredictionRisk(actor){
  const canMove=!(actor.enabled===false||actor.hp<=0||actor.escaped||movementBlockers(actor.conditions).length);
  if(actor.stageWord880!==undefined||actor.coreKind!==undefined){
    const resolved=battleRiskTargetInfo(actor,{stageWord880:actor.stageWord880,coreKind:actor.coreKind,originalCore:actor.originalCore,canMove});
    if(!resolved.complete)throw Error(resolved.reason);
    return {...resolved,upRisk:actor.originalCoreUpRisk??3};
  }
  // StatusUid::Stage D03F3C: side 0 slots 0..7, side 1 slots 8..17.
  // Network registered Denpa on side 0 use the live Core branch; enemy
  // slots have low16 & FFF8 != 0 and therefore always use OriginalCore.
  const registeredEnemy=!!actor.registration&&actor.side===1;
  if(registeredEnemy&&!actor.originalCore)throw Error('registered-original-core-missing');
  const info=coreAntennaRisk(registeredEnemy?actor.originalCore:{groupUid:actor.antenna.groupUid,level:actor.level,ap:actor.ap});
  // D1C8A8 always delegates the priority flag to OriginalCore, even when
  // GetRisk takes the live Stage branch. Never substitute depleted live AP.
  if(actor.originalCore)info.topPriority=coreAntennaRisk(actor.originalCore).topPriority;
  // D1B364: IsEnable, IsDead, IsEscape, then five movement-blocking states.
  // FinCommand/processed is a separate turn-order flag, not this CanMove test.
  if(actor.enabled===false||actor.hp<=0||actor.escaped||movementBlockers(actor.conditions).length)info.risk=Math.trunc(info.risk*80/100);
  return {...info,targetFlag:battleConditionValue(actor,'0x870000AD')!==0,
    // D0CFF0 returns 3; D1C974 delegates UpRisk to OriginalCore.
    upRisk:actor.originalCoreUpRisk??3,attack:battleCurrentStats(actor).atk};
}


// Simulator RNG, intentionally independent of the game's server/protocol.
// Plain data keeps speculative transaction clones from consuming the real stream.
function refreshSimulationRandom(state,{seed}={}) {
 const next=structuredClone(state);
 delete next.simulationRandom;
 for(const p of next.parties)for(const a of p.members.filter(Boolean))delete a.joinRandSeed;
 initializeSimulationRandom(next,{seed});
 if(next.basic)next.basic.battleSeed=next.simulationRandom.seed;
 return next;
}
function initializeSimulationRandom(state,{seed}={}) {
  if(state.simulationRandom)throw new Error('乱数は初期化済みです');
  if(seed===undefined){
    const bytes=new Uint32Array(1);
    seed=globalThis.crypto?.getRandomValues?globalThis.crypto.getRandomValues(bytes)[0]:Math.floor(Math.random()*0x100000000);
  }
  integer(seed,'simulation seed',0,0xffffffff);
  state.simulationRandom={algorithm:'lcg32-v1',seed,value:seed,draws:0,trace:[]};
  for(const party of state.parties)for(const actor of party.members.filter(Boolean)){
    if(actor.joinRandSeed===undefined)actor.joinRandSeed=simulationRandomU32(state,`join-seed:${actor.side}:${actor.slot}`);
  }
  return state.simulationRandom;
}
function simulationRandomStep(rng) {
  if(rng?.algorithm!=='lcg32-v1')throw new Error('ツール用乱数の初期化が必要です');
  integer(rng.value,'random state',0,0xffffffff);integer(rng.draws,'draw count',0,Number.MAX_SAFE_INTEGER-1);
  rng.value=(Math.imul(rng.value,1664525)+1013904223)>>>0;rng.draws++;
  return rng.value;
}
function simulationRandomDraw(state,size,label){
  if(typeof label!=='string'||!label.length)throw Error('Random draw label is required');
  const rng=state.simulationRandom;
  if(rng?.algorithm!=='lcg32-v1')throw Error('ツール用乱数の初期化が必要です');
  if(rng.trace!==undefined&&!Array.isArray(rng.trace))throw Error('Random trace must be an array');
  // Commit only after the entire rejection sample succeeds.
  const work={...rng},drawsBefore=rng.draws,valueBefore=rng.value,rawValues=[];
  const limit=size===null?0x100000000:Math.floor(0x100000000/size)*size;
  let raw;do{raw=simulationRandomStep(work);rawValues.push(raw);}while(raw>=limit);
  const value=size===null?raw:raw%size;
  const entry={label,size,value,drawsBefore,drawsAfter:work.draws,valueBefore,valueAfter:work.value,rawValues};
  rng.value=work.value;rng.draws=work.draws;(rng.trace??=[]).push(entry);
  return value;
}
function simulationRandomU32(state,label='u32') {
  return simulationRandomDraw(state,null,label);
}
function simulationRandRange(state,size,label='range') {
  integer(size,'random range',1,0xffffffff);
  return simulationRandomDraw(state,size,label);
}
// Compatible with damage.mjs's randRange(size,label) dependency.
// Bind to the working state inside a transaction, not an outer live state.
function simulationRandomAdapter(state) {
  if(!state.simulationRandom)throw new Error('ツール用乱数の初期化が必要です');
  return {randRange:(size,label)=>simulationRandRange(state,size,label)};
}


// DecideSubReflect 93D1CC: generate per-type snapshots, process 0..6, clear at end.
// Completion concerns this phase only, not DecideSubHitReturn or the whole command.
function battleRunReflectionPhase(state,options={}) {
  const {battleVersion,sideMap,resolveOtherTurn}=options;
  const work=structuredClone(state),steps=[];
  const finishResults=options.finishResults??(work.resultBookkeeping?((s,context)=>finishReflectionResults(s,context,{sideMap,battleVersion})):undefined);
  const canHitAction=options.canHitAction??(typeof options.coreFor==='function'?((actor,turn)=>{
    const gate=battleReflectionTargetEligibility(work,actor,turn,{coreFor:options.coreFor});
    if(!gate.complete)throw new Error(gate.reason);
    return gate.code;
  }):undefined);
  work.reflectionLists??=createReflectionLists();
  const pending=(reason,turn)=>({complete:false,nextState:null,reason,pendingTurn:turn,steps});
  for(let reflectType=0;reflectType<7;reflectType++){
    const turns=battleReflectionTurns(work,work.reflectionLists,{reflectType,sideMap});
    for(const turn of turns){
      const jackingBefore=battleConditionValue(work.parties[turn.target.side].members[turn.target.slot],'0x8700005F')!==0;
      let outcome;
      if([2,3,4,6].includes(reflectType)){
        if(typeof canHitAction!=='function'||typeof finishResults!=='function')return pending('reflection-hit-or-after-unresolved',turn);
        outcome=reflectType===2?battleResolveReflectedCure(work,turn,{canHitAction,applyCure:options.applyCure,canClear:options.canClear,battleVersion,coreFor:options.coreFor,sideMap}):reflectType===6?battleResolveReflectedHeal(work,turn,{canHitAction,battleVersion}):battleResolveReflectedDamage(work,[turn],{complete:true,battleVersion,canHitAction,sideMap});
        if(outcome.complete===false)return pending(outcome.reason,turn);
        // The generated reflection path has concrete bookkeeping when the caller
        // supplies the round's existing resultBookkeeping; never reset it here.
        outcome.results=outcome.results.map(result=>({...result,nativeInitialization:initializeReflectionResult(turn,{sideMap})}));
        const finished=finishResults(work,{turn,outcome,jackingBefore});
        if(finished?.complete!==true)return pending('reflection-result-effects-unresolved',turn);
      }else if(typeof canHitAction==='function'&&typeof finishResults==='function'&&(typeof options.coreFor==='function'||typeof options.canWrite==='function')){
        outcome=battleResolveReflectedCondition(work,turn,{canHitAction,battleVersion,sideMap,coreFor:options.coreFor,canWrite:options.canWrite,canMove:options.canMove});
        if(!outcome.complete)return pending(outcome.reason,turn);
        outcome.results=outcome.results.map(result=>({...result,nativeInitialization:initializeReflectionResult(turn,{sideMap})}));
        if(finishResults(work,{turn,outcome,jackingBefore})?.complete!==true)return pending('reflection-result-effects-unresolved',turn);
      }else{
        if(typeof resolveOtherTurn!=='function')return pending('reflection-type-unresolved',turn);
        outcome=resolveOtherTurn(work,turn);
        if(outcome?.complete!==true||!Array.isArray(outcome.results))return pending('reflection-type-unresolved',turn);
      }
      // Counter advancement belongs to the result processor, exactly once per
      // retained native result. No guessed initial Impl+C is installed here.
      steps.push({turn,outcome});
    }
  }
  work.reflectionLists=createReflectionLists();
  return {complete:true,nextState:work,steps,reason:'reflection-phase-resolved',scope:'DecideSubReflect'};
}


// UseResultCoreHit 95352C/953538/95355C -> Core::AddParamValue D1B5C0.
// Apply an already generated successful result. Eligibility and lotteries occur
// before this entry; HP recovery skips dead actors, revival omits that skip.
function battleApplyRecoveryResult(actor,{actionType,amount}={}){
  integer(actionType,'Action type',0,255);integer(amount,'Result+58',0,0xffffffff);
  const hp=[0x32,0x37,0x9c,0x9e].includes(actionType),ap=[0x34,0x9f].includes(actionType);
  if(!hp&&!ap)throw Error('Action is not a recovery result');
  const key=hp?'hp':'ap',before=actor[key],maximum=actor.initialStats[key];
  integer(before,'current '+key,0,hp?0xffffff:127);
  integer(maximum,'maximum '+key,hp?1:0,hp?0xffffff:127);
  if(before>maximum)throw Error('Current resource exceeds its maximum');
  if(hp&&actionType!==0x37&&before===0)return {resource:key,before,after:before,gain:0,applied:false,reason:'dead-target'};
  const after=Math.min(maximum,before+amount);
  actor[key]=after;
  return {resource:key,before,after,gain:after-before,applied:true};
}


// GetResultHitReflectHpHeal 94EA2C / 94EABC–94EAE0: saved amount, type 2.
// Code 6 has version/turn-dependent result branches and is not a silent skip.
function reflectedHealResult({reflectType,damage,canHitCode,battleVersion,turnFlag,resultWord18,actionFlags}={}) {
  integer(reflectType,'ReflectType',0,6);integer(canHitCode,'CanHitAction',0,0xffffffff);
  if(reflectType!==6)return {complete:false,reason:'not-reflected-heal'};
  if(canHitCode!==8){
    const empty={complete:true,omitted:true};
    if(![2,6].includes(canHitCode))return empty;
    if(battleVersion===undefined||typeof turnFlag!=='boolean')return {complete:false,reason:'heal-result-context-unresolved'};
    integer(battleVersion,'BattleVersion',1,9999);
    if(canHitCode===2)return turnFlag&&battleVersion>=3?{complete:true,type:5,kind:'reflected-heal',hpGain:0,damageCode:16,messageUid:'0x850039D4',secondaryDamageCode:16,secondaryMessageUid:'0x850039D4'}:empty;
    if(resultWord18===undefined||actionFlags===undefined)return {complete:false,reason:'heal-result-context-unresolved'};
    integer(resultWord18,'Result+18',0,0xffffffff);integer(actionFlags,'Action+1C',0,0xffffffff);
    const type=resultWord18>=2||(actionFlags&8)!==0||(battleVersion>=3&&turnFlag)?5:3;
    return {complete:true,type,kind:'reflected-heal',hpGain:0,damageCode:15,messageUid:battleVersion>=2&&(actionFlags&0xe00)!==0?'0x8500952C':'0x850039D4'};
  }
  integer(damage,'saved heal amount',0,0x7fffffff);
  return {complete:true,type:2,kind:'reflected-heal',hpGain:damage};
}

// Successful normal HP addition only. Outer UserTop/UserAfter remain separate.
function battleResolveReflectedHeal(state,turn,{canHitAction,battleVersion}={}) {
  if(typeof canHitAction!=='function')return {complete:false,reason:'heal-target-gate-unresolved'};
  const {side,slot}=turn.target;integer(side,'side',0,1);integer(slot,'slot',0,7);
  const actor=state.parties[side].members[slot];if(!actor)throw new Error('回復対象が存在しません');
  const result=reflectedHealResult({...turn,battleVersion,canHitCode:canHitAction(actor,turn)});
  if(!result.complete)return result;
  if(result.omitted)return {complete:true,results:[],deathEvents:[],resultCount:0};
  if(result.type!==2)return {complete:true,results:[{...result,target:{...turn.target},actionUid:turn.actionUid,hpBefore:actor.hp,hpAfter:actor.hp,appliedHpGain:0}],deathEvents:[],resultCount:1};
  integer(actor.hp,'current HP',0,0x7fffffff);integer(actor.initialStats.hp,'max HP',1,0x7fffffff);
  if(actor.hp===0||actor.hp>actor.initialStats.hp)return {complete:false,reason:'special-hp-state-unresolved'};
  const applied=battleApplyRecoveryResult(actor,{actionType:0x9c,amount:result.hpGain});
  const hpBefore=applied.before,hpAfter=applied.after;
  return {complete:true,results:[{...result,target:{...turn.target},actionUid:turn.actionUid,hpBefore,hpAfter,appliedHpGain:hpAfter-hpBefore}],deathEvents:[],resultCount:1};
}


function battleReflectionTargetEligibility(state,actor,turn,{coreFor}={}){
  const action=reflectionActions[turn.actionUid];
  if(!action)return {complete:false,allowed:false,reason:'reflection-action-unresolved'};
  // All 20 audited 9A actions store 0 or 1 at +0C; CanHitAction promotes both to 1.
  return battleResolvedTargetEligibility(state,actor,{type:action.type,flags:action.flags,condition_uid:action.conditionUid,value:1},{coreFor});
}

// GetResultHitReflectConditionAdd 94E198–94E590. Saved value/timer; no lottery.
function reflectedConditionResult(turn,canHitCode,{battleVersion}={}){
  integer(canHitCode,'CanHitAction',0,8);integer(battleVersion,'BattleVersion',1,9999);
  const action=reflectionActions[turn.actionUid];
  if(![0,1,5].includes(turn.reflectType)||action?.type!==0x9a)throw new Error('状態付与の反射行動が必要です');
  const common={kind:'reflected-condition',actionUid:turn.actionUid,target:{...turn.target}};
  if(canHitCode===8){
    integer(turn.damage,'saved condition value',-0x80000000,0x7fffffff);
    integer(turn.flags,'saved condition duration',0,15);
    return {...common,type:2,damageCode:0,conditionCode:0,messageUid:action.messageUid,conditionResult:{uid:action.conditionUid,value:turn.damage,turns:turn.flags,success:true,mode:'execute'}};
  }
  if([0,1,7].includes(canHitCode))return null;
  if(typeof turn.turnFlag!=='boolean')throw new Error('Turn+2Cの有無が必要です');
  if(canHitCode===2)return turn.turnFlag&&battleVersion>=3?{...common,type:5,damageCode:16,conditionCode:16,messageUid:'0x850039D4',secondaryMessageUid:'0x850039D4'}:null;
  integer(turn.resultWord18,'Result+18',0,0xffffffff);
  const type=turn.resultWord18>1||(action.flags&8)!==0||(battleVersion>=3&&turn.turnFlag)?5:3;
  const code=({3:16,4:5,5:4,6:15})[canHitCode];
  return {...common,type,damageCode:code,conditionCode:code,messageUid:'0x850039D4',secondaryMessageUid:'0x850039D4'};
}

function battleResolveReflectedCondition(state,turn,{canHitAction,battleVersion,coreFor,canWrite,sideMap=[0,1],canMove}={}){
  if(typeof canHitAction!=='function')return {complete:false,reason:'condition-target-gate-unresolved'};
  integer(turn.target.side,'side',0,1);integer(turn.target.slot,'slot',0,7);
  const actor=state.parties[turn.target.side].members[turn.target.slot];
  if(!actor)throw new Error('状態付与対象がありません');
  const result=reflectedConditionResult(turn,canHitAction(actor,turn),{battleVersion});
  if(!result)return {complete:true,results:[],resultCount:0};
  if(result.type===2){
    if(typeof coreFor!=='function'&&typeof canWrite!=='function')return {complete:false,reason:'condition-write-context-unresolved'};
    const applied=battleApplyConditionHitEffects(state,actor,result.conditionResult,{battleVersion,sideMap,coreFor,canWrite,canMove});
    if(!applied.complete)return applied;
  }
  return {complete:true,results:[result],resultCount:1};
}


// UseResultCoreHitConditionAdd 954890–95493C. This is the state/action-right
// tail of a generated condition hit, not a new eligibility check or lottery.
function battleApplyConditionHitEffects(state,actor,result,{battleVersion,sideMap,coreFor,canWrite,canMove}={}){
  integer(battleVersion,'BattleVersion',1,9999);
  if(!state.parties.some(p=>p.members.includes(actor)))throw Error('状態付与対象が戦闘に存在しません');
  if(result?.mode!=='execute'||result.success!==true)throw Error('成功した状態付与結果が必要です');
  if(typeof canMove!=='function'&&!Number.isFinite(actor.hp))return {complete:false,reason:'condition-post-hit-movement-unresolved'};
  const copy={...actor,conditions:structuredClone(actor.conditions)};
  const write=canWrite??(typeof coreFor==='function'?((target,uid)=>battleConditionWriteFlag(target,uid,{coreFor})):undefined);
  if(typeof write!=='function')return {complete:false,reason:'condition-write-context-unresolved'};
  battleApplyCondition(state,copy,result,{canWrite:write});
  const moving=typeof canMove==='function'?canMove(copy):
    (copy.enabled!==false&&copy.hp>0&&!copy.escaped&&!copy.rental&&movementBlockers(copy.conditions).length===0);
  if(typeof moving!=='boolean')return {complete:false,reason:'condition-post-hit-movement-unresolved'};
  const cleared=[];
  if(battleVersion>=7&&(!moving||battleConditionValue(copy,'0x8700005F')!==0)){
    for(const uid of ['0x8700007F','0x87000009']){
      const entry=copy.conditions.find(c=>Number(c.uid)===Number(uid));
      if(!entry||entry.current===0)continue;
      const allowed=write(copy,uid);
      if(typeof allowed!=='boolean')return {complete:false,reason:'condition-write-context-unresolved'};
      if(allowed){Object.assign(entry,resetCondition(entry));cleared.push(uid);}
    }
  }
  let finished,work;
  if(!moving){
    if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(n=>![0,1].includes(n)))throw Error('sideMapが必要です');
    work={...state,finishedOrders:state.finishedOrders?.slice(),parties:state.parties.map(p=>({...p,members:p.members.map(a=>a===actor?copy:a)}))};
    finished=battleFinishCommand(work,{side:sideMap[actor.side],slot:actor.slot},{sideMap});
  }
  actor.conditions=copy.conditions;
  if(work){state.finishedOrders=work.finishedOrders;actor.processed=copy.processed;}
  return {complete:true,cleared,finished};
}


// UseResultCoreHitConditionAdd 95467C–95488C / 954954–954A08.
// The 81 and packed 65 dispatches jump past this ordinary-result branch.
function recordNativeConditionHit(history,{uid,sourceSide,targetSide,targetSlot,battleVersion}){
  integer(battleVersion,'BattleVersion',1,9999);integer(sourceSide,'native source side',0,1);integer(targetSide,'native target side',0,1);integer(targetSlot,'target slot',0,7);
  if(battleVersion<5||sourceSide!==0||targetSide!==1)return;
  const bits={0x8700001a:1,0x87000048:2,0x870000a6:4,0x87000007:8,0x87000074:16,0x87000066:32,0x8700009d:64,0x87000093:128,0x870000bc:256,
    0x87000077:512,0x870000b3:1024,0x8700005f:2048};
  if(battleVersion>=8)Object.assign(bits,{0x870000b8:4096,0x8700009f:8192,0x87000019:32768,0x870000b5:65536});
  const bit=bits[Number(uid)];if(!bit)return;
  if(!Array.isArray(history)||history.length!==8)throw Error('敵状態履歴の8枠が必要です');
  history.forEach(n=>integer(n,'Impl+2CA8',0,0xffffffff));
  history[targetSlot]=(history[targetSlot]|bit)>>>0;
}

// GetResultConditionAdd 949DB0–94A560: normal network antenna, Turn+2C=0.
// Returns a typed target result. Outer list retention/counters and AP are separate.
function battleGenerateConditionAntennaResult(state,source,target,{battleVersion,turnParameter=0,nativeRandomState,coreFor,jackType=0,mode='execute'}={}){
  if(!['predict','execute'].includes(mode))throw Error('Invalid condition result mode');
  integer(battleVersion,'BattleVersion',1,9999);integer(turnParameter,'Turn+1C',0,0xffffffff);
  if(!state.parties.some(p=>p.members.includes(source))||!state.parties.some(p=>p.members.includes(target)))throw Error('戦闘内の使用者・対象が必要です');
  const action=source.antenna?.action;
  if(Number(action?.type)!==0x1c)throw Error('状態付与アンテナActionが必要です');
  integer(jackType,'Jack type',0,3);
  const sameSide=jackType===3?action.side===1:action.side===2;
  if(![1,2].includes(action.side)||sameSide!==(source.side===target.side)||(battleConditionValue(source,'0x8700005F')!==0&&![2,3].includes(jackType)))throw Error('通常アンテナの対象陣営または使用者状態が不正です');
  const gate=battleResolvedTargetEligibility(state,target,action,{coreFor});
  if(!gate.complete)return gate;
  const common={kind:'condition-antenna',actionUid:action.action_uid,source:{side:source.side,slot:source.slot},target:{side:target.side,slot:target.slot},trace:[]};
  const failureType=turnParameter>1||(Number(action.flags)&8)!==0?5:3;
  if(gate.code!==8){
    const code=({1:16,3:16,4:5,5:4,6:15})[gate.code];
    return {complete:true,results:code===undefined?[]:[{...common,type:failureType,conditionCode:code,reason:gate.reason}]};
  }
  // 94A078–94A0FC: flag bit4 tests invincibility after CanHitAction.
  if((Number(action.flags)&16)!==0&&battleConditionValue(target,'0x870000C6')!==0)
    return {complete:true,results:[{...common,type:failureType,conditionCode:12,reason:'invincible-target'}]};
  if(mode==='predict'){
    const conditionResult=battleRollCondition(source,target,{eligible:true,mode,seed:0,coreFor,jackType,battleVersion});
    return {complete:true,results:[{...common,type:conditionResult.success?2:3,conditionResult,reason:conditionResult.reason}]};
  }
  const random=turnStartNativeRandom({...nativeRandomState,battleVersion,turnParameter,sourceJoinSeed:source.joinRandSeed,targetJoinSeed:target.joinRandSeed});
  const conditionResult=battleRollCondition(source,target,{eligible:true,mode:'execute',seed:random.seed,coreFor,jackType,battleVersion});
  const trace=[{label:'condition-outer',seed:random.outerSeed,raw:random.seed},...conditionResult.trace];
  return {complete:true,results:[{...common,type:conditionResult.success?2:3,conditionResult,trace,reason:conditionResult.reason}]};
}

// One target's state effect, transactionally. Full commands own AP and result
// list bookkeeping; no counter is incremented merely by evaluating this target.
function battleResolveConditionAntennaTarget(state,source,target,options={}){
  const generated=battleGenerateConditionAntennaResult(state,source,target,options);
  if(!generated.complete)return generated;
  const row=generated.results[0];
  if(!row)return {...generated,scope:'condition-target-effect'};
  const applied=battleApplyConditionAntennaResult(state,source,target,row,options);
  if(!applied.complete)return applied;
  return {...generated,applied,scope:'condition-target-effect'};
}

// Apply a previously generated result without rechecking the target or rerolling.
function battleApplyConditionAntennaResult(state,source,target,row,options={}){
  if(!state.parties.some(p=>p.members.includes(source))||!state.parties.some(p=>p.members.includes(target)))throw Error('戦闘内の使用者・対象が必要です');
  if(Number(source.antenna?.action?.type)!==0x1c||row.actionUid!==source.antenna.action.action_uid||row.kind!=='condition-antenna')throw Error('状態付与結果のActionが一致しません');
  if(row.source?.side!==source.side||row.source?.slot!==source.slot||row.target?.side!==target.side||row.target?.slot!==target.slot)throw Error('状態付与結果の対象が一致しません');
  integer(row.type,'condition result type',0,5);
  if(row.type!==2)return {complete:true,applied:false};
  if(Number(row.conditionResult?.uid)!==Number(source.antenna.action.condition_uid))throw Error('状態付与結果のUIDが一致しません');
  const {battleVersion,sideMap}=options;
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(n=>![0,1].includes(n)))throw Error('sideMapが必要です');
  const work=structuredClone(state),copy=work.parties[target.side].members[target.slot];
  let applied;
  if(Number(row.conditionResult.uid)===0x87000081&&row.conditionResult.turns===0){
    if(!work.resultBookkeeping?.deathRecord)return {complete:false,reason:'round-death-record-unresolved'};
    if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(n=>![0,1].includes(n)))throw Error('sideMapが必要です');
    const reset=deathConditionState(copy.conditions);copy.conditions=reset.conditions;copy.hp=0;
    battleRecordDeathPositions(work,[{target:row.target}],{sideMap});
    const action=source.antenna.action;
    recordNativeResultDeath(work.resultBookkeeping.deathRecord,{sourceSide:sideMap[source.side],targetSide:sideMap[target.side],targetSlot:target.slot,flags64:0,
      action:{type:0x1c,flags:Number(action.flags),subUid:Number(action.condition_uid)}},{battleVersion});
    const tail=battleApplyConditionHitEffects(work,copy,{uid:'0x00000000',value:0,turns:0,mode:'execute',success:true},options);
    if(!tail.complete)return tail;
    applied={complete:true,kill:true,damage:target.hp,hpBefore:target.hp,hpAfter:0,changes:reset.changes};
  }else{
    applied=battleApplyConditionHitEffects(work,copy,row.conditionResult,options);
    if(!applied.complete)return applied;
    recordNativeConditionHit(work.resultBookkeeping?.enemyConditionHistory,{uid:row.conditionResult.uid,sourceSide:sideMap[source.side],targetSide:sideMap[target.side],targetSlot:target.slot,battleVersion});
  }
  target.conditions=copy.conditions;target.hp=copy.hp;if(copy.gutsUsed!==undefined)target.gutsUsed=copy.gutsUsed;
  if(copy.processed!==undefined)target.processed=copy.processed;
  if(work.finishedOrders)state.finishedOrders=work.finishedOrders;
  if(work.lastDeadSlots)state.lastDeadSlots=work.lastDeadSlots;
  if(applied.kill)state.resultBookkeeping.deathRecord=work.resultBookkeeping.deathRecord;
  if(work.resultBookkeeping?.enemyConditionHistory)state.resultBookkeeping.enemyConditionHistory=work.resultBookkeeping.enemyConditionHistory;
  return {...applied,scope:'condition-target-effect'};
}


// UseResultCoreUserTop 952B00, 952C48–952CA0. Resource subsection only.
// Called on retained results BEFORE applying the target effect. A failure result
// is not automatically free: the native first-target flag determines the charge.
function battleApplyResultApCost(state,resultBytes,action,{sideMap}={}){
  if(!(resultBytes instanceof Uint8Array)||resultBytes.byteLength!==0xec)throw Error('0xEC byteの戦闘結果が必要です');
  const r=new DataView(resultBytes.buffer,resultBytes.byteOffset,resultBytes.byteLength);
  if(r.getUint8(0x4c)===0)return {complete:true,charged:0,reason:'not-first-target'};
  integer(Number(action?.action_uid),'result Action UID',0,0xffffffff);
  if(Number(action.action_uid)!==r.getUint32(0x38,true))throw Error('結果の実行ActionとAP情報が一致しません');
  integer(Number(action.flags),'Action flags',0,0xffffffff);
  const cost=(Number(action.flags)>>>1)&3;
  if(cost===0||r.getUint32(0x70,true)!==0)return {complete:true,charged:0,reason:cost===0?'zero-cost-action':'result-resource-override'};
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw Error('sideMapが必要です');
  const nativeSide=r.getUint32(4,true),slot=r.getUint32(8,true);
  integer(nativeSide,'native source side',0,1);integer(slot,'source slot',0,7);
  const actor=state.parties[sideMap.indexOf(nativeSide)]?.members[slot];
  if(!actor)throw Error('AP消費元がありません');
  integer(actor.ap,'current AP',0,0x7fffffff);
  const flags=state.resultBookkeeping?.changedActors;
  if(!Array.isArray(flags)||flags.length!==20||flags.some(v=>typeof v!=='boolean'))throw Error('変更個体フラグ20枠が必要です');
  const before=actor.ap,after=Math.max(0,before-cost);
  actor.ap=after;flags[nativeSide*10+slot]=true;
  return {complete:true,cost,charged:before-after,before,after,source:{side:actor.side,slot:actor.slot}};
}

// UserTop 9530EC–953164: consume condition90 before the target's effect,
// except the explicitly exempt action types, self-setting conditions and items.
function battleApplyUserTopConditionReset(state,resultBytes,action,{sideMap,coreFor}={}){
  if(!(resultBytes instanceof Uint8Array)||resultBytes.byteLength!==0xec)throw Error('0xEC byteの戦闘結果が必要です');
  const r=new DataView(resultBytes.buffer,resultBytes.byteOffset,resultBytes.byteLength);
  if(r.getUint8(0x4c)===0)return {complete:true,cleared:false};
  const type=Number(action.type);integer(type,'Action type',0,255);
  if(type===0||type===0x1f||(type>=0x96&&type<0xa0)||(type===0x1c&&[0x87000090,0x870000ac].includes(Number(action.condition_uid)))||r.getUint32(0x34,true)!==0)return {complete:true,cleared:false};
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw Error('sideMapが必要です');
  const nativeSide=r.getUint32(4,true),slot=r.getUint32(8,true);
  integer(nativeSide,'native source side',0,1);integer(slot,'source slot',0,7);
  const actor=state.parties[sideMap.indexOf(nativeSide)]?.members[slot];
  if(!actor)throw Error('状態解除元がありません');
  const condition=actor.conditions.find(c=>Number(c.uid)===0x87000090);
  if(!condition||condition.current===0)return {complete:true,cleared:false};
  const canWrite=battleConditionWriteFlag(actor,'0x87000090',{coreFor});
  if(typeof canWrite!=='boolean')return {complete:false,reason:'condition-write-context-unresolved'};
  const flags=state.resultBookkeeping?.changedActors;
  if(!Array.isArray(flags)||flags.length!==20||flags.some(v=>typeof v!=='boolean'))throw Error('変更個体フラグ20枠が必要です');
  const after=canWrite?resetCondition(condition):condition;
  Object.assign(condition,after);flags[nativeSide*10+slot]=true;
  return {complete:true,cleared:canWrite};
}

// Enemy-only UserTop history shared by retained attack and antenna results. Brain AP failure
// type4 is a separate route; its saved six-entry list is not synthesized here.
function battleApplyAntennaUserTopHistory(state,resultBytes,{sideMap,coreFor}={}){
  if(!(resultBytes instanceof Uint8Array)||resultBytes.byteLength!==0xec)throw Error('0xEC byteの戦闘結果が必要です');
  const r=new DataView(resultBytes.buffer,resultBytes.byteOffset,resultBytes.byteLength);
  if(r.getUint8(0x4c)===0||r.getUint32(4,true)!==1)return {complete:true};
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw Error('sideMapが必要です');
  const slot=r.getUint32(8,true);integer(slot,'source slot',0,7);
  const actor=state.parties[sideMap.indexOf(1)]?.members[slot];if(!actor)throw Error('使用者がありません');
  const command=r.getUint32(0x20,true),first=r.getUint8(0x1e)!==0;
  const jacked=actor.conditions.some(c=>Number(c.uid)===0x8700005f&&c.current!==0);
  const needsCore=first||(!jacked&&command>=1&&command<=6);
  const kind=needsCore?(actor.coreKindFlags??coreFor?.(actor)?.kind):undefined;
  if(needsCore&&kind===undefined)return {complete:false,reason:'core-kind-flags-unresolved'};
  if(needsCore)integer(kind,'Core+888',0,0xffffffff);
  const book=state.resultBookkeeping;
  if(!Array.isArray(book?.changedActors)||book.changedActors.length!==20||book.changedActors.some(v=>typeof v!=='boolean'))throw Error('変更個体フラグ20枠が必要です');
  if(!Array.isArray(book.enemyActionHistory)||book.enemyActionHistory.length>30||new Set(book.enemyActionHistory).size!==book.enemyActionHistory.length)throw Error('敵行動履歴が不正です');
  const uid='0x'+r.getUint32(0x38,true).toString(16).padStart(8,'0').toUpperCase();
  if(kind===2){
    if(!jacked&&command>=1&&command<=6){actor.prevCommand=command;actor.prevCommandLoaded=true;actor.prevCommandDirty=true;}
    if(first)actor.firstActionState={loaded:true,dirty:true,value:true};
  }
  book.changedActors[10+slot]=true;
  if(Number(uid)!==0&&!book.enemyActionHistory.includes(uid)&&book.enemyActionHistory.length<30)book.enemyActionHistory.push(uid);
  return {complete:true};
}


// Retained 1C results only, in native list order. This effect batch deliberately
// does not stand in for UserAfter reactions or FinCommand/the whole command.
function battleApplyConditionResultBatch(state,records,options={}){
  return battleApplyAntennaEffectResultBatch(state,records,options);
}

// Shared retained-result application for condition-add and cure antennas.
function battleApplyAntennaEffectResultBatch(state,records,options={}){
  if(!Array.isArray(records))throw Error('保持済み結果の配列が必要です');
  const work=structuredClone(state),book=work.resultBookkeeping,events=[];
  integer(book?.resultCounter,'Impl+C',0,0xffffffff);
  const {sideMap}=options;
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(n=>![0,1].includes(n)))throw Error('sideMapが必要です');
  for(const record of records){
    if(record.kind==='no-use'){
      const bytes=record.nativeResult;
      if(!(bytes instanceof Uint8Array)||bytes.byteLength!==0xec)throw Error('NoUseの結果初期化情報が必要です');
      const native=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
      const side=sideMap.indexOf(native.getUint32(4,true)),slot=native.getUint32(8,true);
      const actor=work.parties[side]?.members[slot];
      if(!actor||native.getUint32(0,true)!==5||native.getUint32(0x38,true)!==Number(record.actionUid)||native.getUint32(0xc,true)!==Number(actor.antenna?.action?.action_uid)||native.getUint32(0x3c,true)!==sideMap[side]||native.getUint32(0x40,true)!==slot)throw Error('NoUseの使用者・元Action・対象が一致しません');
      const before=book.resultCounter;
      applyNoUseResult(work,record,options);
      events.push({source:{side,slot},target:{side,slot},type:5,kind:'no-use',counterBefore:before,counterAfter:book.resultCounter});
      continue;
    }
    if(![2,3,5].includes(record.type))throw Error('状態付与の保持済み結果が必要です');
    const source=work.parties[record.source?.side]?.members[record.source?.slot],target=work.parties[record.target?.side]?.members[record.target?.slot];
    if(!source||!target)throw Error('結果の使用者・対象がありません');
    const bytes=record.nativeInitialization;
    if(!(bytes instanceof Uint8Array)||bytes.length!==0xec)throw Error('結果の初期化情報が必要です');
    const r=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
    if(r.getUint32(4,true)!==sideMap[source.side]||r.getUint32(8,true)!==source.slot||r.getUint32(0x3c,true)!==sideMap[target.side]||r.getUint32(0x40,true)!==target.slot)throw Error('結果の内部対象が一致しません');
    const before=book.resultCounter;
    const action=source.antenna?.action,type=Number(action?.type);
    if(![0x1c,0x35,0x36].includes(type)||record.actionUid!==action.action_uid)throw Error('状態付与・解除アンテナの結果が必要です');
    if(r.getUint32(0x38,true)!==Number(action.action_uid))throw Error('結果ヘッダーのActionが一致しません');
    if(type===0x35&&(record.kind!=='cure'||Number(record.conditionUid)!==Number(action.condition_uid)))throw Error('解除結果のUIDが一致しません');
    const resource=battleApplyResultApCost(work,bytes,action,{sideMap});
    const history=battleApplyAntennaUserTopHistory(work,bytes,options);
    if(!history.complete)return {...history,nextState:null};
    const reset=battleApplyUserTopConditionReset(work,bytes,action,options);
    if(!reset.complete)return {...reset,nextState:null};
    const effect=type===0x1c?battleApplyConditionAntennaResult(work,source,target,record,options):
      battleApplyCureResult(work,target,action,record,{sideMap,canClear:(actor,uid)=>battleConditionWriteFlag(actor,uid,{coreFor:options.coreFor})});
    if(!effect.complete)return {...effect,nextState:null};
    if(record.type===2){
      if(!Array.isArray(book.changedActors)||book.changedActors.length!==20||book.changedActors.some(v=>typeof v!=='boolean'))throw Error('変更個体フラグ20枠が必要です');
      book.changedActors[sideMap[target.side]*10+target.slot]=true;
    }
    if(r.getUint8(0x4c)!==0)book.lastResult=structuredClone(record);
    book.resultCounter=(before+1)>>>0;
    events.push({source:{...record.source},target:{...record.target},type:record.type,resource,reset,effect,counterBefore:before,counterAfter:book.resultCounter});
  }
  return {complete:true,nextState:work,events,scope:'antenna-resource-effect-batch'};
}


// One resolved native Turn, before UseResult starts. All target lotteries read
// the same pre-application state and result counter; no effect or AP is applied.
function battleGenerateAntennaEffectTurn(state,turnBytes,options={}){
  if(!(turnBytes instanceof Uint8Array)||turnBytes.byteLength!==0x40)throw Error('0x40 byteのBattleTurnが必要です');
  const {sideMap,mode='execute'}=options;
  if(!['predict','execute'].includes(mode))throw Error('Invalid antenna effect mode');
  if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(s=>![0,1].includes(s)))throw Error('sideMapが必要です');
  const t=new DataView(turnBytes.buffer,turnBytes.byteOffset,turnBytes.byteLength);
  const sourceSide=sideMap.indexOf(t.getUint32(0,true)),sourceSlot=t.getUint32(4,true);
  if(sourceSide<0||sourceSlot>7)throw Error('ネット対戦の使用者位置が必要です');
  const actor=state.parties[sourceSide]?.members[sourceSlot],action=actor?.antenna?.action;
  if(!actor||Number(action?.action_uid)!==t.getUint32(8,true))throw Error('Turnの使用者・アンテナが一致しません');
  const type=Number(action.type);
  if(![0x1c,0x35,0x36].includes(type)||t.getUint32(0x2c,true)!==0)return {complete:false,reason:'unsupported-effect-turn'};
  const generated=[],turnParameter=t.getUint32(0x1c,true),mask=t.getUint32(16,true);
  if(mask&~0xffff)throw Error('ネット対戦8人ずつの対象マスクが必要です');
  for(let bit=0;bit<16;bit++){
    if(!(mask&(1<<bit)))continue;
    const nativeSide=bit>>>3,side=sideMap.indexOf(nativeSide),slot=bit&7,target=state.parties[side]?.members[slot];
    if(!target)throw Error('Turnの対象が存在しません');
    if((options.jackType??t.getUint32(0x30,true))===3&&side===sourceSide&&slot===sourceSlot)continue;
    let rows;
    if(type===0x1c){
      const result=battleGenerateConditionAntennaResult(state,actor,target,{...options,turnParameter});
      if(!result.complete)return {...result,results:[]};
      rows=result.results;
    }else{
      // ConditionEnd/DisPlus prediction returns before CanHitAction.
      const gate=mode==='predict'?{complete:true}:battleResolvedTargetEligibility(state,target,action,options);
      if(!gate.complete)return {...gate,results:[]};
      const row=cureAntennaResult(action,{battleVersion:options.battleVersion,mode,turnParameter,canHitCode:gate.code,
        randomContext:{...options.nativeRandomState,sourceJoinSeed:actor.joinRandSeed,targetJoinSeed:target.joinRandSeed}});
      rows=row?[{...row,source:{side:sourceSide,slot:sourceSlot},target:{side,slot}}]:[];
    }
    generated.push(...rows.map(row=>({...row,nativeInitialization:initializeBattleResult(turnBytes,nativeSide,slot)})));
  }
  const finalized=finalizeAntennaGeneratedResults(generated,turnBytes,{isDenpa:actor.isDenpa});
  return {complete:true,...finalized,generatedResults:generated,scope:'resolved-antenna-turn-generation'};
}


// GetResultHitReflectConditionEnd 94E7FC–94E824: Action+8, not saved value.
function reflectedCureResult(turn,canHitCode) {
  integer(canHitCode,'CanHitAction',0,0xffffffff);
  if(turn.reflectType!==2)return {complete:false,reason:'not-reflected-cure'};
  const action=reflectionActions[turn.actionUid];
  if(!action||action.type!==0x9b)return {complete:false,reason:'cure-action-unresolved'};
  if(canHitCode!==8){
    if(![2,6].includes(canHitCode))return {complete:true,omitted:true};
    const {battleVersion,turnFlag,resultWord18}=turn;
    if(battleVersion===undefined||typeof turnFlag!=='boolean')return {complete:false,reason:'cure-result-context-unresolved'};
    integer(battleVersion,'BattleVersion',1,9999);
    if(canHitCode===2&&! (turnFlag&&battleVersion>=3))return {complete:true,omitted:true};
    let type=5;
    if(canHitCode===6){
      if(resultWord18===undefined)return {complete:false,reason:'cure-result-context-unresolved'};
      integer(resultWord18,'Result+18',0,0xffffffff);
      type=resultWord18>1||(action.flags&8)!==0||(battleVersion>=3&&turnFlag)?5:3;
    }
    return {complete:true,type,kind:'reflected-cure',damageCode:16,conditionCode:16,messageUid:'0x850039D4',secondaryMessageUid:'0x850039D4'};
  }
  return {complete:true,type:2,kind:'reflected-cure',conditionUid:action.conditionUid,messageUid:action.messageUid,conditionValue:1,damageCode:0,conditionCode:0};
}

// Resolve/apply each successful condition clear against the transaction state.
function battleResolveReflectedCure(state,turn,{canHitAction,applyCure,canClear,battleVersion,coreFor,sideMap}={}) {
  if(canClear===undefined&&typeof coreFor==='function')canClear=(actor,id)=>battleConditionWriteFlag(actor,id,{coreFor});
  if(!applyCure&&typeof canClear==='function')applyCure=(s,a,r)=>battleApplyCureResult(s,a,reflectionActions[turn.actionUid],r,{canClear,sideMap});
  if(typeof canHitAction!=='function')return {complete:false,reason:'cure-effects-unresolved'};
  integer(turn.target.side,'side',0,1);integer(turn.target.slot,'slot',0,7);
  const actor=state.parties[turn.target.side].members[turn.target.slot];
  if(!actor)throw new Error('状態解除対象がありません');
  const result=reflectedCureResult({...turn,battleVersion:battleVersion??turn.battleVersion},canHitAction(actor,turn));
  if(!result.complete)return result;
  if(result.omitted)return {complete:true,results:[],resultCount:0};
  if(result.type!==2)return {complete:true,results:[{...result,target:{...turn.target},actionUid:turn.actionUid}],resultCount:1};
  if(typeof applyCure!=='function')return {complete:false,reason:'cure-effects-unresolved'};
  const applied=applyCure(state,actor,result);
  if(applied?.complete!==true)return {complete:false,reason:'cure-effects-unresolved'};
  return {complete:true,results:[{...result,target:{...turn.target},actionUid:turn.actionUid}],resultCount:1};
}


// StatusApp2Db::GetCondition D059C8; DB-index order, not actor-state order.
function expandClearCondition(uid) {
  const id=typeof uid==='string'&&/^[0-9a-f]{8}$/i.test(uid)?Number.parseInt(uid,16):Number(uid),bit=new Map([[0x87000006,9],[0x8700000A,11],[0x87000052,10],[0x87000073,8]]).get(id);
  if(bit!==undefined)return {complete:true,uids:conditionRecords.filter(r=>(Number(r.words[14])&(1<<bit))!==0).sort((a,b)=>a.index-b.index).slice(0,199).map(r=>r.uid)};
  // libmolokai.so D05BC0–D05C1C: vector constants plus scalar tail.
  const fixed={
    0x87000016:[0x8700000C,0x87000024,0x87000085,0x870000A0,0x87000004,0x870000A7,0x87000061,0x87000076],
    0x87000065:[0x87000028,0x87000013,0x87000010,0x87000014],
    0x8700008F:[0x87000002,0x87000063,0x87000012,0x870000C7]
  };
  if(fixed[id])return {complete:true,uids:fixed[id].map(n=>'0x'+n.toString(16).toUpperCase())};
  if(id===0)return {complete:true,uids:[]};
  return {complete:true,uids:[conditionRecord('0x'+id.toString(16).padStart(8,'0')).uid]};
}

// UseResultCoreHitConditionEnd: allied clears remove negative deltas and harmful
// positive deltas; enemy clears reset all changed expanded entries.
function battleClearCondition(actor,uid,{ally,canClear}={}) {
  if(typeof ally!=='boolean'||typeof canClear!=='function')return {complete:false,reason:'clear-context-unresolved'};
  const expanded=expandClearCondition(uid);if(!expanded.complete)return expanded;
  const changes=[],states=actor.conditions.map(c=>conditionState(c.uid,c));
  for(const id of expanded.uids){
    const s=states.find(c=>Number(c.uid)===Number(id));if(!s||s.current===s.base)continue;
    const harmful=(Number(conditionRecord(id).words[14])&0x1000)!==0;
    if(ally&&s.current>s.base&&!harmful)continue;
    const allowed=canClear(actor,id); // Core GetConditionFlagData bit0, not eligibility code8.
    if(typeof allowed!=='boolean')return {complete:false,reason:'clear-flag-unresolved'};
    if(!allowed)continue;
    const after=resetCondition(s);changes.push({uid:id,before:{...s},after});Object.assign(s,after);
  }
  actor.conditions=states;
  return {complete:true,changes};
}


// UseResultCoreHit 9535D4–953614, 9536CC–9536E4. Apply an already
// generated clear result; CanRemoveCondition is upstream, never rerolled here.
function battleApplyCureResult(state,actor,action,result,{canClear,sideMap}={}){
  if(!state.parties.some(p=>p.members.includes(actor)))throw Error('解除対象が戦闘に存在しません');
  const type=Number(action?.type);
  if(![0x35,0x36,0x9b].includes(type))throw Error('解除アンテナまたは解除反射Actionが必要です');
  integer(result?.type,'result type',0,5);
  if(result.type!==1&&result.type!==2)return {complete:true,changes:[],applied:false};
  integer(Number(action.flags),'Action flags',0,0xffffffff);
  const copy={...actor,conditions:structuredClone(actor.conditions)};
  const cleared=type===0x36?battleClearPlusConditions(copy,{canClear}):battleClearCondition(copy,result.conditionUid,{ally:((Number(action.flags)>>>6)&3)===2,canClear});
  if(!cleared.complete)return cleared;
  // A directly named Jack cure consumes the target's current action right,
  // even when ClearConditionValue's write flag disallows the actual reset.
  // A compound cure that includes Jack does NOT enter this exact-UID branch.
  let finished;
  if(type!==0x36&&Number(result.conditionUid)===0x8700005f){
    if(!Array.isArray(sideMap)||sideMap.length!==2||new Set(sideMap).size!==2||sideMap.some(n=>![0,1].includes(n)))throw Error('sideMapが必要です');
    const work={...state,finishedOrders:state.finishedOrders?.slice(),parties:state.parties.map(p=>({...p,members:p.members.map(a=>a===actor?copy:a)}))};
    finished=battleFinishCommand(work,{side:sideMap[actor.side],slot:actor.slot},{sideMap});
    state.finishedOrders=work.finishedOrders;
    actor.processed=copy.processed;
  }
  actor.conditions=copy.conditions;
  return {...cleared,applied:true,finished};
}

// StatusApp2Db::GetPlusCondition D05C3C..D05D68. Excludes compound IDs,
// index zero and harmful records; preserve DB order and the 199-entry cap.
function plusConditionUids(){
 const excluded=new Set([0x87000052,0x87000065,0x87000073,0x8700008f,0x87000006,0x8700000a,0x87000016]);
 return conditionRecords.filter(r=>r.index>0&&!excluded.has(Number(r.uid))&&(Number(r.words[14])&0x1000)===0).sort((a,b)=>a.index-b.index).slice(0,199).map(r=>r.uid);
}
// UseResultCoreHitDisPlus 954B68..954C24: only positive deltas reset.
function battleClearPlusConditions(actor,{canClear}={}){
 if(typeof canClear!=='function')return {complete:false,reason:'clear-context-unresolved'};
 const copy={...actor,conditions:structuredClone(actor.conditions)},changes=[];
 for(const uid of plusConditionUids()){
  const s=copy.conditions.find(c=>Number(c.uid)===Number(uid));
  if(!s||s.current<=s.base)continue;
  const cleared=battleClearCondition(copy,uid,{ally:false,canClear});
  if(!cleared.complete)return cleared;
  changes.push(...cleared.changes);
 }
 actor.conditions=copy.conditions;
 return {complete:true,changes};
}

